-- Practical curriculum v3 for Perfect Video (s02-m01 through s02-m03).
-- Existing versions, progress rows, and attempts remain intact; published pointers move atomically.
-- Adds the missing lesson pv03-12 and stores every lesson as a new immutable version.
SET lock_timeout = '5s';

DO $pv_release$
DECLARE
  lesson_spec jsonb;
  block_spec record;
  lesson_uuid uuid;
  previous_version_uuid uuid;
  new_version_uuid uuid;
  new_version_number integer;
  block_uuid uuid;
  validation_result jsonb;
BEGIN
  FOR lesson_spec IN
    SELECT value
    FROM jsonb_array_elements('[{"module_id":"s02-m01","lesson_id":"pv01-01","title":"Избери реален проект и запиши началната точка","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да избереш един реален проект и да опишеш какво знаеш и какво още трябва да провериш","hook":"Преди да мислиш за камерата, трябва да знаеш какво ще промениш с това видео.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избереш един реален проект и да опишеш какво знаеш и какво още трябва да провериш"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Преди да мислиш за камерата, трябва да знаеш какво ще промениш с това видео."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Започни с един проект, който можеш да довършиш в рамките на курса: услуга, продукт, събитие или лична тема. Запиши сегашното състояние, какво знаеш от наблюдение и какво засега е само предположение. Не обещавай резултат преди да имаш доказателство."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Собственик на малко студио иска повече запитвания. Той записва: „Хората питат за цена, но често не разбират какво включва пакетът.“ Това е наблюдение за проверка, не готова диагноза."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое е добра начална точка за учебен проект?","options":[{"id":"a","label":"Реален проблем с поне едно проверимо наблюдение"},{"id":"b","label":"Тема, избрана само защото е популярна"},{"id":"c","label":"Скъп инструмент, който искаш да изпробваш"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Три различни проекта наведнъж"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Опиши проекта с три реда: за кого е, какъв проблем виждаш и какво доказателство вече имаш. Отбележи едно важно неизвестно.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да избереш един реален проект и да опишеш какво знаеш и какво още трябва да провериш","Проектът трябва да е изпълним и да позволява проверка; популярността сама по себе си не доказва нужда."],"nextStep":"Избрал си един проект; отделил си фактите от предположенията; задачата може да се заснеме с наличния ресурс."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-02","title":"Определи за кого е видеото и кога ще го гледа","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да опишеш конкретен зрител чрез ситуация, нужда и контекст на гледане","hook":"„Всички“ не е аудитория, към която можеш да напишеш ясна сцена.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да опишеш конкретен зрител чрез ситуация, нужда и контекст на гледане"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Всички“ не е аудитория, към която можеш да напишеш ясна сцена."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Опиши човека през ситуацията, в която видеото му става полезно: какво се опитва да направи, какво го спира и колко време има. Възрастта или професията могат да помогнат, но не заместват нуждата и контекста. Не приписвай на цяла група мотиви, които не си проверил."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Видео за нови фрийлансъри може да е за човек, който току-що е получил първо запитване и не знае как да оформи оферта — по-конкретно от „млади предприемачи“."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Коя аудитория е най-полезно описана?","options":[{"id":"a","label":"Всички, които използват социални мрежи"},{"id":"b","label":"Само демографски профил без нужда"},{"id":"c","label":"Човек в конкретна ситуация с назована задача и пречка"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Списък от интереси без връзка с видеото"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши описание в едно изречение: „Когато ___, човекът иска ___, но се затруднява от ___.“ Добави къде и в какъв формат вероятно ще гледа видеото.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да опишеш конкретен зрител чрез ситуация, нужда и контекст на гледане","Ситуацията и задачата дават конкретен материал за послание и пример."],"nextStep":"Има назована ситуация; нуждата е наблюдаема; описанието не претендира да представя всички."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-03","title":"Проучи как хората решават проблема си сега","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да събереш наблюдения от реални ситуации, преди да избираш тема и послание","hook":"Ако изследваш само собствените си идеи, рискуваш да решиш проблем, който хората нямат.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да събереш наблюдения от реални ситуации, преди да избираш тема и послание"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Ако изследваш само собствените си идеи, рискуваш да решиш проблем, който хората нямат."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Търси какво прави човекът преди да намери решение: какво пробва, къде се обърква, кой термин използва и какво го кара да отложи. Използвай интервю, коментари, търсения и собствени наблюдения като отделни източници. Записвай точните думи, без да ги редактираш към твоята оферта."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Вместо да питаш „Харесва ли ти приложението?“, попитай „Разкажи ми за последния път, когато планира публикация. Какво направи първо?“"},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кой въпрос дава по-надеждна информация?","options":[{"id":"a","label":"„Харесва ли ти моята идея?“"},{"id":"b","label":"„Разкажи за последния път, когато опита да решиш това.“"},{"id":"c","label":"„Би ли купил продукт, който решава този проблем?“"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"„Смяташ ли, че видеото ми ще стане популярно?“"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Събери пет конкретни сигнала: три от разговори или коментари и два от наблюдение. За всеки отбележи източника и дата.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да събереш наблюдения от реални ситуации, преди да избираш тема и послание","Въпросът за реално минало действие намалява натиска да се хареса на автора и дава конкретни подробности."],"nextStep":"Записал си точни думи; отбелязал си откъде идва сигналът; не си смесил наблюдение с извод."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-04","title":"Задавай въпроси, които не подсказват отговора","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да проведеш кратък разговор без да подтикваш човека към желаното от теб заключение","hook":"„Това полезно ли би ти било?“ почти винаги води до учтиво, но безполезно „да“.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да проведеш кратък разговор без да подтикваш човека към желаното от теб заключение"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Това полезно ли би ти било?“ почти винаги води до учтиво, но безполезно „да“."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Използвай отворени въпроси за последен конкретен случай, стъпките, затруднението и последствията. Изчакай отговора, после поискай пример. Не предлагай решение в самия въпрос. Интервюто не е продажба и не е анкета за одобрение на идеята."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"„Кое е най-трудното в заснемането?“ е общо. „Покажи как подготви последното си видео и къде се забави“ дава действия, време и контекст."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кой въпрос най-малко подсказва отговор?","options":[{"id":"a","label":"„Какво направи последния път, когато това се случи?“"},{"id":"b","label":"„Нали би било по-лесно с моя продукт?“"},{"id":"c","label":"„Искаш ли повече видеа за това?“"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"„Ти също смяташ ли, че този проблем е сериозен?“"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Подготви шест въпроса за разговор с един потенциален зрител. Подчертай въпросите, които започват с „би ли“, и пренапиши ги за минало поведение.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да проведеш кратък разговор без да подтикваш човека към желаното от теб заключение","Въпросът за конкретен минал случай оставя човека свободен да опише и неудобните за нас факти."],"nextStep":"Въпросите са отворени; искаш пример, не съгласие; не споменаваш своя продукт преди описанието на проблема."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-05","title":"Раздели тема, проблем и полезен извод","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да превърнеш широка тема в конкретен проблем и извод за зрителя","hook":"„Фитнес“, „маркетинг“ и „видео“ са категории, не още идеи за конкретен епизод.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превърнеш широка тема в конкретен проблем и извод за зрителя"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Фитнес“, „маркетинг“ и „видео“ са категории, не още идеи за конкретен епизод."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Тема казва областта. Проблемът казва какво се случва на човека. Изводът казва какво разбира или може да направи след видеото. Не е нужно всяко видео да решава целия проблем; избери една честна и изпълнима част."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Тема: звук. Проблем: записаният глас е тих спрямо шума от стаята. Извод: преди нов микрофон премести телефона по-близо и направи тест със слушалки."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кой ред вече съдържа идея за видео?","options":[{"id":"a","label":"„Видео маркетинг“"},{"id":"b","label":"„Осветление“"},{"id":"c","label":"„Шумът в стаята заглушава гласа; първо направи тест от мястото на запис.“"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"„Полезно съдържание за всички“"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши пет теми от проекта си. За всяка добави един наблюдаван проблем и един конкретен извод, който можеш да покажеш.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да превърнеш широка тема в конкретен проблем и извод за зрителя","Изводът свързва наблюдаем проблем с практическа промяна."],"nextStep":"Проблемът се вижда или чува; изводът е ограничен; можеш да го обясниш с реален пример."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-06","title":"Постави цел за зрителя, не за суетна метрика","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да избереш едно желано действие или разбиране и показател, който го приближава","hook":"Гледанията сами по себе си не показват дали видеото е било полезно или е довело до правилното действие.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избереш едно желано действие или разбиране и показател, който го приближава"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Гледанията сами по себе си не показват дали видеото е било полезно или е довело до правилното действие."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Започни с промяната, която видеото иска да направи: зрителят да разбере, запомни, сравни или предприеме действие. После избери показател, свързан с тази цел. Измервай едно основно нещо и използвай допълнителните данни за обяснение, а не за украса."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Обяснително видео може да следи колко хора стигат до демонстрацията и колко запазват видеото; кампания за записване следи завършените формуляри, не само гледанията."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кой показател е най-близо до цел „записване за консултация“?","options":[{"id":"a","label":"Брой използвани преходи в монтажа"},{"id":"b","label":"Брой завършени и валидни заявки"},{"id":"c","label":"Общ брой показвания без контекст"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Личната оценка на автора за видеото"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши целта като „След това видео зрителят ще може/ще направи…“. До нея постави един основен и един диагностичен показател.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да избереш едно желано действие или разбиране и показател, който го приближава","Показателят трябва да измерва желаното действие или да помага да се диагностицира пътят до него."],"nextStep":"Целта описва промяна; основният показател я измерва; знаеш къде ще вземеш данните."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-07","title":"Свържи целта с едно следващо действие","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да избираш действие, което съответства на готовността и нуждата на зрителя","hook":"Не всяко видео трябва да продава; не всяко „последвай ме“ е полезна следваща стъпка.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш действие, което съответства на готовността и нуждата на зрителя"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Не всяко видео трябва да продава; не всяко „последвай ме“ е полезна следваща стъпка."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Подбери действие според контекста: запазване на полезен урок, разглеждане на подробен пример, запитване или покупка. Действието трябва да е ясно, изпълнимо и подкрепено от видеото. Ако искаш няколко неща, подреди ги по приоритет и избери едно основно."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Кратка демонстрация на настройка естествено води към „Запази чеклиста“. Видео за конкретна услуга може да води към страница с цена и условия, ако те са ясни."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какво прави следващото действие уместно?","options":[{"id":"a","label":"То следва от стойността и е реалистично за този етап"},{"id":"b","label":"То е най-агресивният призив, който можеш да кажеш"},{"id":"c","label":"То се добавя по навик към всеки клип"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"То иска три несвързани действия наведнъж"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Избери целта на своя проект и напиши едно основно действие. Обясни защо то е разумно за зрител, който току-що е видял видеото.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да избираш действие, което съответства на готовността и нуждата на зрителя","Контекстът и готовността определят каква молба изглежда полезна, а не натрапена."],"nextStep":"Действието е еднозначно; видеото подготвя за него; обещанията за следващата стъпка са реални."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-08","title":"Формулирай обещание, което можеш да изпълниш","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да опишеш конкретната полза на видеото без гаранции, които не можеш да докажеш","hook":"Силно обещание привлича внимание само ако самото видео го изпълнява.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да опишеш конкретната полза на видеото без гаранции, които не можеш да докажеш"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Силно обещание привлича внимание само ако самото видео го изпълнява."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Формулирай обещанието като полезен резултат в рамките на видеото: какво ще разбере или пробва човекът. Използвай точни глаголи и граници. Избягвай „гарантирано“, „винаги“ и резултат, зависещ от условия, които не контролираш."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"„Ще ти покажа два начина да намалиш шума в стаята“ е проверимо. „Ще направиш студийно аудио за пет минути“ обещава повече, отколкото краткият урок може да гарантира."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое обещание е най-достоверно?","options":[{"id":"a","label":"Гарантира еднакъв резултат на всеки зрител"},{"id":"b","label":"Скрива условията зад думата „магически“"},{"id":"c","label":"Назовава ограничен резултат, който видеото реално показва"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Обещава промяна, която не е част от темата"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши три обещания за една тема: за обяснение, демонстрация и личен опит. Подчертай какво може да се види във видеото като доказателство.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да опишеш конкретната полза на видеото без гаранции, които не можеш да докажеш","Съответствието между обещание и демонстрация изгражда доверие и пази зрителя от подвеждане."],"nextStep":"Ползата е конкретна; границите са ясни; можеш да покажеш доказателството."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-09","title":"Провери какво доказваш и с чие разрешение","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да избираш доказателство, което е относимо, вярно и използвано с разрешение","hook":"Историята на клиент може да е силна, но не е твой материал без съгласие.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш доказателство, което е относимо, вярно и използвано с разрешение"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Историята на клиент може да е силна, но не е твой материал без съгласие."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Преди да използваш числа, препоръки, снимки или клиентски случай, провери източника, периода, условията и правото за употреба. Не представяй единичен успех като типичен резултат. Ако не разполагаш с доказателство, покажи процеса или демонстрация и назови ограничението."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Клиентска препоръка за конкретен резултат може да се ползва с изрично съгласие и контекст. Без него можеш да заснемеш собствена демонстрация със синтетични данни."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога клиентски пример е етично използваем?","options":[{"id":"a","label":"Когато резултатът е впечатляващ, дори ако е изключение"},{"id":"b","label":"Когато твърдението е вярно, контекстът е ясен и има разрешение"},{"id":"c","label":"Когато името е скрито, независимо от чувствителните детайли"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Когато авторът смята, че клиентът няма да забележи"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Избери едно твърдение от своята идея. Запиши какво би го потвърдило, откъде идват данните и какво разрешение ти трябва.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да избираш доказателство, което е относимо, вярно и използвано с разрешение","Точността и съгласието са част от производството, не редакция в последния момент."],"nextStep":"Проверил си произхода; не обобщаваш единичен случай; имаш разрешение или анонимизираш безопасно."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-10","title":"Изгради теми, към които можеш да се връщаш","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да организираш устойчиви теми около нуждите на аудиторията и своята доказуема експертиза","hook":"Календарът се изпразва, когато всяка публикация трябва да бъде напълно нова идея.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да организираш устойчиви теми около нуждите на аудиторията и своята доказуема експертиза"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Календарът се изпразва, когато всяка публикация трябва да бъде напълно нова идея."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Избери няколко тематични полета, които се повтарят в работата ти: чести въпроси, решения, демонстрации и грешки. Темата е полезна, когато имаш право и доказателство да говориш по нея, аудиторията я търси и можеш да я поддържаш без изкуствено раздуване."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Майстор по ремонти може да развива: диагностика преди покупка, демонстрация на безопасна дребна поправка и как да избере специалист."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Коя тема е най-устойчива за поредица?","options":[{"id":"a","label":"Повтарящи се въпроси, за които имаш компетентност и примери"},{"id":"b","label":"Тренд, който няма връзка с работата ти"},{"id":"c","label":"Една тема, избрана само по броя гледания на конкурент"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Списък от продукти, които искаш да рекламираш"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Събери десет реални въпроса. Групирай ги в три–пет теми и запиши към всяка какво можеш да покажеш или провериш.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да организираш устойчиви теми около нуждите на аудиторията и своята доказуема експертиза","Тематичната рамка идва от пресечната точка между нужда, компетентност и производствен ресурс."],"nextStep":"Във всяка тема има въпроси от хората; можеш да покажеш доказателство; темата не разчита на един тренд."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-11","title":"Генерирай идеи от въпросите, не от празен лист","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да превръщаш реален въпрос в няколко различни, приложими видео идеи","hook":"Когато търсиш само „гениална идея“, пропускаш малките задачи, за които хората вече търсят помощ.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превръщаш реален въпрос в няколко различни, приложими видео идеи"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Когато търсиш само „гениална идея“, пропускаш малките задачи, за които хората вече търсят помощ."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"За всеки въпрос опитай различни форми: обясни избор, сравни два случая, покажи процес, коригирай грешка или разкажи ограничен личен опит. Разнообрази гледната точка, без да измисляш нов факт. Повтарящото се въпросче може да даде серия, не само един клип."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Въпросът „Как избера микрофон?“ може да стане: тест от разстояние, сравнение в шумна стая, чеклист за покупка или пример кога външен микрофон не помага."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какво прави варианта истински различен?","options":[{"id":"a","label":"Сменя само заглавието, а повтаря същото обяснение"},{"id":"b","label":"Добавя несвързан тренд"},{"id":"c","label":"Сменя начина на показване или зрителската задача"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Копира чужд клип дума по дума"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Вземи един въпрос от интервюто си и измисли пет различни формата. До всеки запиши какъв материал трябва да заснемеш.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да превръщаш реален въпрос в няколко различни, приложими видео идеи","Нов формат променя преживяването или доказателството, а не само външния надпис."],"nextStep":"Идеите произлизат от реален въпрос; всяка има различен подход; ресурсът за заснемане е посочен."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-12","title":"Избери идея с ясни критерии","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да сравниш идеи по полезност, доказуемост и възможност за производство","hook":"Най-забавната идея не винаги е най-подходящата за целта или бюджета.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да сравниш идеи по полезност, доказуемост и възможност за производство"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Най-забавната идея не винаги е най-подходящата за целта или бюджета."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Оцени всяка идея по четири въпроса: има ли реална нужда, можеш ли да подкрепиш извода, вижда ли се ползата във видео и можеш ли да го произведеш навреме. Това е практичен филтър, не математическа формула: слаб резултат трябва да доведе до промяна или отхвърляне."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Сравни идея за сложен експертен разговор, който изисква графики и интервю, с 30-секундна демонстрация, която решава често задаван въпрос в наличното студио."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кой избор е най-професионален?","options":[{"id":"a","label":"Идея, която конкурентът вече е направил успешно"},{"id":"b","label":"Идея с реална нужда, доказателство и изпълнимо производство"},{"id":"c","label":"Идея с най-много ефекти независимо от целта"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Идея с обещание, което още не можеш да докажеш"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Оцени три идеи по четирите критерия с ниско/средно/високо и обясни коя избираш.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да сравниш идеи по полезност, доказуемост и възможност за производство","Критериите помагат да направиш обоснован избор, без да се преструваш, че точният рейтинг е обективен."],"nextStep":"Използвал си еднакви критерии; записал си неизвестните; избрал си изпълним вариант."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-13","title":"Начертай пътя на зрителя до видеото","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да опишеш какво знае и какво още му трябва преди следващата стъпка","hook":"Видео може да е ясно само за хора, които вече познават продукта.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да опишеш какво знае и какво още му трябва преди следващата стъпка"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Видео може да е ясно само за хора, които вече познават продукта."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Помисли какво зрителят вече знае, какво не разбира и какво трябва да се случи след гледането. Ранният контакт изисква повече контекст; познатата аудитория може да стигне по-бързо до подробности. Не използвай „фунията“ като задължителна формула — тя е карта за нужната информация."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"За непозната услуга първо покажи проблема и начина на работа. За човек, който вече сравнява доставчици, дай условията, процеса и доказателствата."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какво трябва да се промени при адаптация за зрител, който не познава автора?","options":[{"id":"a","label":"Добави нужния контекст и доказателство преди да поискаш ангажимент"},{"id":"b","label":"Остави само вътрешни съкращения"},{"id":"c","label":"Намали контекста, защото кратките видеа винаги печелят"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Поискай покупка още преди да обясниш офертата"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Опиши един път от първото виждане до целевото действие. Отбележи въпросите на зрителя на всяка стъпка.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да опишеш какво знае и какво още му трябва преди следващата стъпка","Съобщението трябва да отговаря на текущото знание и намерение на зрителя."],"nextStep":"Знаеш какво вече знае; назовал си следващия въпрос; действието съответства на готовността."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-14","title":"Избери формат според задачата и мястото на гледане","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да съобразиш формат, продължителност и начин на гледане с идеята","hook":"Един и същ кадър не е автоматично подходящ за всяка платформа и екран.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да съобразиш формат, продължителност и начин на гледане с идеята"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Един и същ кадър не е автоматично подходящ за всяка платформа и екран."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Започни от мястото на гледане и изискваното действие. Вертикален кратък клип, интервю, екранен запис и хоризонтален урок имат различни ограничения. Проверявай актуалните технически изисквания на целевата платформа преди експорт — интерфейсът и препоръките се променят."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Демонстрация на мобилно приложение може да иска вертикален екранен запис с крупни елементи; урок с таблица и сравнения може да се чете по-добре хоризонтално."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога трябва да провериш конкретните размери и ограничения на платформата?","options":[{"id":"a","label":"Само след като файлът вече е публикуван"},{"id":"b","label":"Никога — има един постоянен стандарт за всички платформи"},{"id":"c","label":"Преди снимане и отново преди експортиране"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Само ако редакторът покаже грешка"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Избери един формат за проекта. Напиши причината, къде ще се гледа, какво трябва да се вижда и кое ще провериш преди публикация.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да съобразиш формат, продължителност и начин на гледане с идеята","Актуалните платформи имат различни изисквания и интерфейси; проверката преди производство спестява повторна работа."],"nextStep":"Форматът има връзка със задачата; знаеш какъв екран ще гледа човекът; отбелязал си изисквания за проверка."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-15","title":"Разгледай референция по решенията, не само по усещането","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да разложиш пример на конкретни визуални и редакционни решения","hook":"„Изглежда професионално“ не ти казва какво да направиш със собствената си сцена.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да разложиш пример на конкретни визуални и редакционни решения"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Изглежда професионално“ не ти казва какво да направиш със собствената си сцена."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"При гледане на референция отбележи кадриране, светлина, движение, звук, монтажен ритъм и връзката им със смисъла. Записвай функцията на избора: какво прави видим, какво скрива и какво кара зрителя да очаква. Не приемай популярността за доказателство за причината. За по-дълбок визуален анализ виж Bruce Block, The Visual Story: композицията, линията, светлината и цветът работят заедно със смисъла на сцената."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Клипът използва близък кадър в момента на важен детайл. Полезният извод не е „винаги снимай близо“, а „приближи кадъра, когато детайлът носи информация“."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое наблюдение може да се приложи?","options":[{"id":"a","label":"„Цветът е хубав.“"},{"id":"b","label":"„Крупният план прави детайла четим в този момент.“"},{"id":"c","label":"„Авторът има много гледания, затова всяка негова настройка е правилна.“"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"„Трябва да направя същото видео.“"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Избери два референтни клипа и отбележи по пет конкретни решения и ефекта им. Добави кое би променил за своя проект.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да разложиш пример на конкретни визуални и редакционни решения","Описанието на функцията позволява да пренесеш принципа, без да копираш резултата."],"nextStep":"Назовал си видими решения; свързал си ги с ефект; отделил си тенденция от доказана причина."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-16","title":"Вземи принципа от референцията, не чуждото видео","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да създадеш оригинален подход, като отделиш механиката от израза","hook":"Копираният hook или кадър звучи и изглежда като чужда работа, дори темата да е твоя.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да създадеш оригинален подход, като отделиш механиката от израза"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Копираният hook или кадър звучи и изглежда като чужда работа, дори темата да е твоя."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Отдели структурата, която работи, от конкретната фраза, музика, кадър или персонаж. После приложи принципа към собствена истина, контекст и доказателство. Провери правата за музика, изображения, кадри и лични истории. При съмнение използвай собствен материал."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Вместо да повтаряш чуждото „три грешки“, вземи принципа „конкретна полза + ясно ограничение“ и го приложи към свой реален тест."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое е етично адаптиране?","options":[{"id":"a","label":"Използваш общ принцип, собствен пример и проверени права"},{"id":"b","label":"Сменяш две думи в чуждия сценарий"},{"id":"c","label":"Повтаряш монтажа и музиката, защото клипът е публичен"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Използваш чуждо лице без разрешение"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Избери една референция. Запиши какъв принцип ще пренесеш и три видими елемента, които ще направиш различно.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да създадеш оригинален подход, като отделиш механиката от израза","Публичната достъпност не означава разрешение за повторна употреба."],"nextStep":"Посочил си какво учиш; доказателството е твое; проверил си права и съгласие."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-17","title":"Напиши едностраничен творчески бриф","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да събереш цел, аудитория, обещание, доказателство и производствени ограничения","hook":"Ако брифът е само тема, снимачният екип ще трябва да измисли останалото на място.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да събереш цел, аудитория, обещание, доказателство и производствени ограничения"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Ако брифът е само тема, снимачният екип ще трябва да измисли останалото на място."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Брифът е кратък работен договор: какъв резултат търсим, за кого, какво казваме, на какво стъпва твърдението, какъв формат произвеждаме и как ще оценим. Той не е литературен текст; той помага на сценариста, оператора и клиента да вземат съгласувани решения."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"За продуктово демо запиши: зрителят сравнява два варианта; обещанието е да види разликата; доказателството е едно и също действие при еднакви условия; CTA е към спецификациите."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое поле не трябва да липсва в бриф за производство?","options":[{"id":"a","label":"Любимият цвят на автора без връзка с бранда"},{"id":"b","label":"Списък с всички възможни теми за година"},{"id":"c","label":"Как ще разберем дали видеото изпълнява целта"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Подробен монтажен ефект за всеки кадър преди идеята"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Създай бриф до една страница със седем полета: цел, аудитория, ситуация, основна идея, доказателство, формат/ограничения, показател.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да събереш цел, аудитория, обещание, доказателство и производствени ограничения","Брифът трябва да свърже творческото решение с резултат и ограничения."],"nextStep":"Всички седем полета са ясни; фактът е отделен от допускането; екипът знае кой одобрява."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-18","title":"Намери ъгъла, който прави темата конкретна","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да избираш гледна точка, която добавя смисъл към позната тема","hook":"Темата може да е обща; разликата често е в конкретния въпрос, случай или ограничение.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш гледна точка, която добавя смисъл към позната тема"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Темата може да е обща; разликата често е в конкретния въпрос, случай или ограничение."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Ъгълът е обещаният начин да разгледаш темата: за кого, в каква ситуация и с какъв извод. Избягвай изкуствената противоположност само за провокация. Силен ъгъл може да е сравнение, демонстрация, ограничение, възражение или история — ако поддържаш твърдението."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Тема: светлина. Ъгъл: „Как да снимаш лице до прозорец в облачен ден без да прегориш фона“ — има сцена и проверим избор."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое заглавие съдържа конкретен ъгъл?","options":[{"id":"a","label":"„Никой не иска да ти каже истината за светлината“"},{"id":"b","label":"„Как осветихме лице до прозорец, когато фонът беше ярък“"},{"id":"c","label":"„Всичко за осветлението“"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"„Най-доброто видео на годината“"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши пет ъгъла за една тема: сравнение, грешка, стъпка, ограничение и реален случай. Избери един според брифа.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да избираш гледна точка, която добавя смисъл към позната тема","Ъгълът обещава какво точно ще разгледа клипът и може да се изпълни с материал."],"nextStep":"Ъгълът е различим; има отношение към зрителя; можеш да покажеш ситуацията."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-19","title":"Планирай какво трябва да се види","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да превърнеш брифа в материал, който зрителят може да наблюдава","hook":"Обяснение без видим пример често оставя зрителя с много думи и малко разбиране.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превърнеш брифа в материал, който зрителят може да наблюдава"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Обяснение без видим пример често оставя зрителя с много думи и малко разбиране."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Преди да напишеш кадри, попитай какво зрителят трябва да види, чуе или сравни, за да повярва на извода. Списъкът може да включва демонстрация, екранен запис, предмет, схема или интервю. Не снимай покритие само за да запълниш монтажа."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"За урок за стабилизация заснеми един и същ маршрут ръчно и с опора, без да сменяш скоростта или кадъра между тестовете."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какво прави допълнителния кадър необходим?","options":[{"id":"a","label":"Показва информация, която иначе трябва само да бъде заявена"},{"id":"b","label":"Запълва точно три секунди независимо от темата"},{"id":"c","label":"Повтаря същото действие от друг ъгъл без причина"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Използва преход, който харесваш"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Състави списък от пет доказателствени кадъра. До всеки напиши кое твърдение подкрепя и какво трябва да е видимо.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да превърнеш брифа в материал, който зрителят може да наблюдава","Кадърът трябва да носи доказателство или да ориентира зрителя."],"nextStep":"Всеки кадър има функция; знаеш какво се вижда; условията на сравнението са последователни."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-20","title":"Оцени място, време и налични ресурси","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да направиш план, който може да се произведе при реалните ограничения","hook":"Най-добрата идея е безполезна, ако не можеш да я снимаш с времето и ресурсите си.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да направиш план, който може да се произведе при реалните ограничения"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Най-добрата идея е безполезна, ако не можеш да я снимаш с времето и ресурсите си."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Провери място, шум, светлина, достъп, хора, предмети, разрешения и резервен вариант. Отдели задължителното от желаното. Ако една сцена зависи от време, клиент или локация, уточни това преди снимане, не в деня на монтажа."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Интервю в оживено кафене може да изглежда естествено, но звукът прави материала неизползваем. Резервът е тиха стая и два атмосферни кадъра отвън."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое е добър производствен резерв?","options":[{"id":"a","label":"Надежда, че шумът ще се оправи в монтажа"},{"id":"b","label":"Още една тема, която не влиза във времето"},{"id":"c","label":"Алтернативно място или кадър, който пази смисъла"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Покупка на техника без тест"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Направи таблица: нужда, кой я осигурява, срок, резервен план. Отбележи три риска и една евтина корекция.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да направиш план, който може да се произведе при реалните ограничения","Резервът трябва да запази ключовата информация, не просто да прикрие липсващ реквизит."],"nextStep":"Назовал си зависимости; има отговорник и срок; резервът е проверим."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-21","title":"Подреди деня на снимане по зависимости","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да подредиш задачи така, че хората и ресурсите да чакат възможно най-малко","hook":"Заснемането се бави, когато един необходим детайл се открие след пристигането на екипа.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да подредиш задачи така, че хората и ресурсите да чакат възможно най-малко"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Заснемането се бави, когато един необходим детайл се открие след пристигането на екипа."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Планирай реда спрямо локация, наличност на хора и непрекъснатост. Групирай кадри по настройка, но записвай промените, за да останат дрехи, предмети и посока последователни. Остави време за тест и повторен дубъл."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Ако гостът е наличен само час, заснеми първо интервюто, после отделните кадри на мястото, вместо да го чакаш след b-roll."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое трябва да е първо?","options":[{"id":"a","label":"Кадърът, който изисква реквизит, който още не е пристигнал"},{"id":"b","label":"Задача с най-строго ограничение или зависимост"},{"id":"c","label":"Най-лесният кадър, за да се почувства екипът продуктивен"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Монтажът преди заснемането"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Подреди шест производствени задачи по време и зависимост. Добави прозорец за техническа проверка и резерв.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да подредиш задачи така, че хората и ресурсите да чакат възможно най-малко","Приоритетът следва риска и наличността на ресурса."],"nextStep":"Синхронизирал си участниците; имаш буфер; заснемането е подредено по зависимости."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-22","title":"Направи техническа и редакционна проверка преди запис","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да хванеш проблеми със звук, кадър, съгласие и съдържание преди основния дубъл","hook":"Един кратък тест може да спести час монтаж на неизползваем материал.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да хванеш проблеми със звук, кадър, съгласие и съдържание преди основния дубъл"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Един кратък тест може да спести час монтаж на неизползваем материал."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Преди да снимаш основната версия, направи 10–20 секунден тест. Провери фокус, експозиция, баланс на цвета, четимост, звук на слушалки, място за надписи и права/съгласие. Тестът се гледа на устройство, подобно на това, което ще използва зрителят."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Водещият звучи ясно на камера, но слушалките разкриват климатик. Премести се преди да запишеш целия разговор."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое е най-надеждното време за слушане на записания звук?","options":[{"id":"a","label":"Веднага след тестовия дубъл със слушалки"},{"id":"b","label":"Само след финалния експорт"},{"id":"c","label":"Когато клиентът вече е одобрил монтажа"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Никога, ако индикаторът за ниво се движи"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Създай preflight чеклист с осем точки за своята локация. Запиши кой проверява всяка точка.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да хванеш проблеми със звук, кадър, съгласие и съдържание преди основния дубъл","Индикаторът показва сигнал, но не показва дали звукът е чист, разбираем и без шум."],"nextStep":"Проверил си тестов файл; прослушал си го; съгласията и рамката са изчистени."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-23","title":"Планирай как ще научиш от резултата","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да формулираш хипотеза и правило за следваща итерация","hook":"Ако смениш едновременно хук, тема, дължина и CTA, няма да знаеш какво е повлияло.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да формулираш хипотеза и правило за следваща итерация"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Ако смениш едновременно хук, тема, дължина и CTA, няма да знаеш какво е повлияло."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Преди публикуване запиши какво очакваш да се случи и какво действие ще предприемеш при различни резултати. Едно сравнение не доказва универсален закон; разглеждай аудиторията, разпространението и сезона. Избирай метрика, която съответства на целта."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Ако хората стигат до демонстрацията, но не кликат към подробностите, провери CTA и целевата страница преди да заключиш, че темата е слаба."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какъв тест помага да се разбере причината?","options":[{"id":"a","label":"Променя пет елемента, после избира по усещане"},{"id":"b","label":"Сравнява видеа с различна аудитория и различна цел без бележки"},{"id":"c","label":"Променя един основен елемент и държи останалото възможно най-стабилно"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Обявява победителя по един коментар"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши: „Ако ___, това може да означава ___; следващия път ще променя ___ и ще измеря ___.“ Посочи алтернативно обяснение.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да формулираш хипотеза и правило за следваща итерация","Контролираният малък тест не премахва всички влияния, но позволява по-разумен извод."],"nextStep":"Хипотезата е записана предварително; метриката е свързана с целта; алтернативите са отчетени."},"required":true,"points":1}]},{"module_id":"s02-m01","lesson_id":"pv01-24","title":"Събери брифа и плана за производство","subtitle":"Практика за създатели и видео специалисти","estimated_minutes":14,"objective":"да предадеш проект, по който сценаристът и снимачният екип могат да започнат работа","hook":"Първият модул има стойност, когато идеята вече е достатъчно ясна за следващата стъпка.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да предадеш проект, по който сценаристът и снимачният екип могат да започнат работа"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Първият модул има стойност, когато идеята вече е достатъчно ясна за следващата стъпка."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Обедини аудиторията и ситуацията, нуждата, целта, обещанието, доказателството, формата, производствените условия и показателя. Остави въпросите, които трябва да провериш, видими. Не крий неизвестното под уверени формулировки."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Добър бриф за клип за услуга обяснява на кого помага, какво може да се покаже, кое твърдение е доказано, колко време е на разположение и какъв е следващият ход."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кой пакет е готов за предаване?","options":[{"id":"a","label":"Дълъг текст с идеи без аудитория и цел"},{"id":"b","label":"Бриф, доказателства, производствени ограничения и начин за оценка"},{"id":"c","label":"Само заглавие и музикална референция"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Списък с оборудване без план за видео"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Попълни брифа и отбележи едно неизвестно, което трябва да провериш преди сценария. В отговора напиши кой може да потвърди това и как ще го направиш.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"quality_gate","type":"checklist","title":"Самопроверка преди предаване","content":{"items":[{"id":"check-1","text":"Целта и аудиторията са конкретни.","required":true},{"id":"check-2","text":"Обещанието се подкрепя с видим материал или проверим източник.","required":true},{"id":"check-3","text":"Неизвестните и допусканията са отбелязани.","required":true},{"id":"check-4","text":"Форматът и производствените ограничения са реалистични.","required":true},{"id":"check-5","text":"Следващото действие и показателят са ясни.","required":true}]},"required":true,"points":2},{"key":"submission","type":"submission","title":"Предай работата си","content":{"prompt":"Качи или сподели едностраничния бриф и списъка с пет кадъра. Включи цел, аудитория, обещание, доказателство или източник, формат, ограничения, разрешения и начин за оценка. Използвай само материал, за който имаш право.","accept":"link,file"},"required":true,"points":4},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да предадеш проект, по който сценаристът и снимачният екип могат да започнат работа","Предаването трябва да позволява на следващия специалист да продължи без да отгатва намерението."],"nextStep":"Брифът е кратък; източниците и неизвестните са ясни; планът е реалистичен."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-01","title":"Остави на видеото една ясна работа","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да сведеш сценария до една промяна, която зрителят трябва да разбере или направи","hook":"Сценарият става мъгляв, когато едновременно обяснява продукта, историята на бранда и всички услуги.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да сведеш сценария до една промяна, която зрителят трябва да разбере или направи"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Сценарият става мъгляв, когато едновременно обяснява продукта, историята на бранда и всички услуги."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Една основна идея не означава, че можеш да кажеш само едно изречение. Тя означава, че всяка част помага на една цел. Запиши целта, посланието и какво не влиза в този клип; останалото може да стане следващ епизод."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Видео за избиране на микрофон може да обясни какво да тестваш в шумна стая. То не е нужно да включва и цялата история на аудиотехниката."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое е признак за фокус?","options":[{"id":"a","label":"Всеки аргумент и пример подкрепя едно обещание"},{"id":"b","label":"Видеото покрива колкото може повече теми"},{"id":"c","label":"CTA въвежда нова оферта, която не е спомената преди"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Няма изречение, което да казва какво зрителят печели"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Вземи брифа от Модул 1. Напиши посланието с едно изречение и отдели три интересни, но несъществени идеи за други видеа.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да сведеш сценария до една промяна, която зрителят трябва да разбере или направи","Единствената идея е принцип на подредба, а не лимит на броя факти."],"nextStep":"Посланието е конкретно; изключил си странични теми; CTA не противоречи на целта."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-02","title":"Намери гледната точка преди първия ред","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да превърнеш темата от брифа в конкретна гледна точка за сценария","hook":"Две видеа могат да говорят за една тема, но едното да е полезно, а другото — общо.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превърнеш темата от брифа в конкретна гледна точка за сценария"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Две видеа могат да говорят за една тема, но едното да е полезно, а другото — общо."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Избери какво точно ще защитаваш или показваш: решение, сравнение, ограничение, наблюдение или личен случай. Гледната точка трябва да следва доказателството ти. Ако най-силният материал е демонстрация, не започвай със спорно универсално твърдение."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Тема „домашно осветление“ може да има ъгъл „какво променя местоположението на прозореца“ — и показваш това с два контролирани кадъра."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Коя гледна точка е готова за сценарий?","options":[{"id":"a","label":"Звучи провокативно, но няма проверим пример"},{"id":"b","label":"Повтаря брифа дословно, без избор на подход"},{"id":"c","label":"Има конкретен извод и материал, който може да го подкрепи"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Изисква чуждо доказателство без разрешение"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши три гледни точки към своята тема. За всяка посочи кое доказателство ще види зрителят.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да превърнеш темата от брифа в конкретна гледна точка за сценария","Гледната точка е полезна само ако е подкрепена от това, което можеш да покажеш."],"nextStep":"Темата и гледната точка са различни; доказателството е посочено; твърдението не е по-широко от материала."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-03","title":"Напиши хук, който изпълнява обещанието","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да започнеш сценария с конкретно твърдение, въпрос или образ, който видеото после оправдава","hook":"Зрителят губи доверие, когато началото обещава „тайна“, а след това получава общ съвет.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да започнеш сценария с конкретно твърдение, въпрос или образ, който видеото после оправдава"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Зрителят губи доверие, когато началото обещава „тайна“, а след това получава общ съвет."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Хукът — първата реплика, действие или кадър — помага да се разбере, защо да останеш. Конкретност и уместност са по-ценни от громкост. Провери, че в основната част наистина отговаряш на въпроса или показваш заявения резултат."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"„Ето как направих снимка с по-малко шум без нова камера“ работи само ако клипът показва условията, сравнението и ограничението на теста."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какво трябва да е вярно за добрия хук?","options":[{"id":"a","label":"Обещава максимален резултат независимо от условията"},{"id":"b","label":"Основната част изпълнява точното очакване, което началото създава"},{"id":"c","label":"Началото крие темата до последната секунда"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Използва изненада, несвързана с видеото"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши пет начални версии: конкретно твърдение, въпрос, видим резултат, грешка и ситуация. Отбележи доказателството за всяка.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да започнеш сценария с конкретно твърдение, въпрос или образ, който видеото после оправдава","Хукът създава очакване; съответствието му с основната част пази доверие."],"nextStep":"Написал си няколко различни отваряния; всяко е вярно; видиш ли доказателството във видеото."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-04","title":"Започни с действие, образ или реплика","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да избираш начин на отваряне според това каква информация може да се покаже най-рано","hook":"Понякога първият кадър е достатъчно ясен; понякога зрителят има нужда от едно изречение контекст.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш начин на отваряне според това каква информация може да се покаже най-рано"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Понякога първият кадър е достатъчно ясен; понякога зрителят има нужда от едно изречение контекст."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Началото може да е действие, резултат, въпрос, конкретна реплика или директен контекст. Избери това, което най-бързо ориентира зрителя. Ако образът е двусмислен, добави кратък надпис или реплика; не очаквай монтажът да обясни сам."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"В клип за поправка на люлеещ се статив можеш да започнеш с видимото клатене, после да кажеш какво да провериш."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога е по-добре да добавиш реплика още в първия кадър?","options":[{"id":"a","label":"Когато самият образ не дава достатъчно контекст"},{"id":"b","label":"Когато искаш да скриеш несвързана услуга"},{"id":"c","label":"Във всяко видео, независимо от сцената"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Когато няма нищо видимо и не планираш да го снимаш"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Направи storyboard с три различни първи кадъра за своя сценарий. За всеки запиши какво зрителят разбира без звук и със звук.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да избираш начин на отваряне според това каква информация може да се покаже най-рано","Звукът, изображението и надписите заедно трябва да ориентират зрителя."],"nextStep":"Първият кадър е четим; има вариант без звук; репликата добавя информация."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-05","title":"Подреди сценария на ясни части","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да изградиш последователност от контекст, напрежение, избор и резултат","hook":"Силен hook не спасява сценарий, който не знае накъде отива.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да изградиш последователност от контекст, напрежение, избор и резултат"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Силен hook не спасява сценарий, който не знае накъде отива."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Направи скелет преди репликите. Един работещ вариант е: ситуация → какво пречи → какво проверяваме или правим → какво следва. За история използвай избор и последствие; за демонстрация — условие, действие и наблюдаем резултат. Това са модели за подреждане, не задължителни формули. За допълнителна работа по причинно-следствена структура виж John Yorke, Into the Woods; използвай моделите като оптика, не като задължителна схема."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Ученикът снима пред прозорец, фонът избледнява, променя позицията и показва сравнението. Всеки смислова стъпка добавя нова информация."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое е полезно между началото и финала?","options":[{"id":"a","label":"Повторение на обещанието без развитие"},{"id":"b","label":"Нова тема, въведена без връзка"},{"id":"c","label":"Всяка част добавя информация или подготвя следващата"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Дълга история за автора преди контекст"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши четири до шест смислови стъпки за видеото си. До всеки напиши, какво ново научава зрителят.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да изградиш последователност от контекст, напрежение, избор и резултат","Смисловите стъпки поддържат причинно-следствената връзка, не просто времето."],"nextStep":"Всяка част е различна; примерът идва навреме; финалът следва от показаното."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-06","title":"Създай напрежение без да подвеждаш","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да поддържаш интерес с въпрос, препятствие и отговор, които са реални за темата","hook":"Празната интрига задържа секунда, но разрушава доверието, ако отговорът е дребен или липсва.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да поддържаш интерес с въпрос, препятствие и отговор, които са реални за темата"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Празната интрига задържа секунда, но разрушава доверието, ако отговорът е дребен или липсва."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Напрежението идва от нещо, което зрителят иска да разбере: коя настройка влияе, защо опитът се проваля, какъв избор ще проработи. Назови въпроса честно, дай достатъчно контекст и затвори го с отговор. Не създавай фалшива спешност."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"„Ще покажа защо лицето изглежда различно при 0.5x и 1x“ създава конкретен въпрос; „няма да повярваш“ не казва какво ще научиш."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Коя оставена интрига е честна?","options":[{"id":"a","label":"Отлага отговора без да добавя информация"},{"id":"b","label":"Задава конкретен въпрос и го затваря с проверим отговор"},{"id":"c","label":"Споменава опасност, несвързана с темата"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Казва, че има „тайна“, но не дава метод"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши въпрос в началото, една пречка в средата и точен отговор във финала. Подчертай обещанията, които не можеш да изпълниш.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да поддържаш интерес с въпрос, препятствие и отговор, които са реални за темата","Любопитството работи, когато обещанието е истинско и зрителят получава затваряне."],"nextStep":"Въпросът е конкретен; развитието дава нови данни; финалът отговаря."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-07","title":"Дай новата информация в правилния ред","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да подредиш информацията така, че зрителят да може да следва решението","hook":"Точният съвет може да изгуби смисъл, ако се появи преди зрителят да разбере проблема.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да подредиш информацията така, че зрителят да може да следва решението"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Точният съвет може да изгуби смисъл, ако се появи преди зрителят да разбере проблема."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Първо установи ситуацията и термините, които са нужни. После покажи изборите или стъпките, и чак тогава добави нюанс, изключение и следващо действие. Остави детайл за следващото видео, ако без него текущият извод остава разбираем."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Преди да говориш за бял баланс, покажи защо две лампи дават различен оттенък. После назови настройката и как да я заключиш."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога трябва да въведеш специализиран термин?","options":[{"id":"a","label":"Когато е нужен за следващата стъпка и можеш веднага да го обясниш"},{"id":"b","label":"В първия ред, защото така звучи професионално"},{"id":"c","label":"След финала, когато няма време за обяснение"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Никога, дори ако терминът помага"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Размести пет точки от своя сценарий в логичен ред. До всяка запиши какво трябва зрителят да знае преди нея.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да подредиш информацията така, че зрителят да може да следва решението","Термините са полезни, когато подпомагат действието, не когато показват авторитет."],"nextStep":"Редът следва нуждата; термините са обяснени; няма предпоставка, която зрителят не знае."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-08","title":"Покажи процеса, вместо само да го твърдиш","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да превърнеш обяснението в наблюдаема демонстрация","hook":"„Вярвай ми“ е слабо доказателство, когато можеш да покажеш действието.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превърнеш обяснението в наблюдаема демонстрация"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Вярвай ми“ е слабо доказателство, когато можеш да покажеш действието."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Използвай кадър, екранен запис, предмет, схема или сравнение, за да направиш причината видима. При сравнение контролирай основните условия и кажи кое се е променило. Ако визуализацията е опростена или възстановена, маркирай я честно."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"За да покажеш разликата между микрофон близо и далеч, запиши една и съща реплика в една стая със същите настройки и посочи разстоянието."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое сравнение дава по-чист извод?","options":[{"id":"a","label":"Два различни дни, стаи и микрофони без обяснение"},{"id":"b","label":"Сравнение с обработен аудиозапис, представено като необработен"},{"id":"c","label":"Един и същ контекст с една планирана промяна"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Две случайни снимки без етикети"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Добави към всеки основен смислова стъпка кадър или предмет, който носи информация. Ако няма такъв, обясни защо.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да превърнеш обяснението в наблюдаема демонстрация","Когато условията се менят заедно, зрителят не може да разбере причината за разликата."],"nextStep":"Промяната е видима; условията са записани; обработката е обозначена."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-09","title":"Подкрепи твърдението с проверимо доказателство","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да използваш източник, пример или тест, който действително подкрепя твърдението","hook":"Увереният тон не замества доказателството — особено при числа, здраве, финанси и клиентски резултати.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш източник, пример или тест, който действително подкрепя твърдението"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Увереният тон не замества доказателството — особено при числа, здраве, финанси и клиентски резултати."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Посочи откъде идва фактът, кога е събран и при какви условия важи. Разграничавай източник, собствен опит и мнение. Не разширявай малък тест до универсален извод. Ако доказателството е ограничено, кажи границата и не обещавай същия резултат на всеки."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"„В нашия тест телефонът записва по-чисто на 20 cm“ описва конкретен тест. „Този телефон винаги има най-добрия звук“ е много по-широко твърдение."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое твърдение е най-отговорно?","options":[{"id":"a","label":"„Гарантирано работи“ след един опит"},{"id":"b","label":"„В този тест, при тези условия, разликата се вижда тук.“"},{"id":"c","label":"„Всички експерти са съгласни“, без източник"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Цитат на клиент, използван без съгласие"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Маркирай всяко твърдение в черновата като факт, наблюдение или мнение. До факта запиши източника, до наблюдението — условията.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да използваш източник, пример или тест, който действително подкрепя твърдението","Точната рамка позволява зрителят да оцени приложимостта на твърдението."],"nextStep":"Разделил си факт и мнение; източникът е проверим; условията не са скрити."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-10","title":"Обясни трудна идея с точен пример","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да използваш аналогия или демонстрация, без тя да изкривява темата","hook":"Аналогията помага само ако прави понятие по-разбираемо и не създава нова заблуда.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш аналогия или демонстрация, без тя да изкривява темата"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Аналогията помага само ако прави понятие по-разбираемо и не създава нова заблуда."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Избери познато действие, което споделя важната структура с идеята ти. Обясни коя част е подобна и къде сравнението спира. За техническа тема последвай аналогията с реална демонстрация или контрапример."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Фокусът прилича на избиране на мястото, където читателят гледа първо, но камерата фокусира дистанция в образа; аналогията не обяснява дълбочина на рязкост."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какво завършва полезната аналогия?","options":[{"id":"a","label":"Посочва и сходството, и границата на сравнението"},{"id":"b","label":"Използва впечатляваща метафора без връзка с реалността"},{"id":"c","label":"Заменя всички точни термини с жаргон"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Обещава, че аналогията обяснява цялата теория"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Обясни едно понятие с аналогия в две изречения. Добави едно изречение за границата ѝ и кадър, който ще потвърди обяснението.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да използваш аналогия или демонстрация, без тя да изкривява темата","Границата предпазва лесното сравнение да не стане погрешен модел."],"nextStep":"Аналогията е кратка; границата е ясна; примерът проверява реалното понятие."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-11","title":"Пиши в своя глас, не в рекламна поза","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да редактираш репликите така, че да звучат естествено и да пазят фактите","hook":"Зрителят чува, когато текстът се опитва да изглежда по-убедителен от самия автор.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да редактираш репликите така, че да звучат естествено и да пазят фактите"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Зрителят чува, когато текстът се опитва да изглежда по-убедителен от самия автор."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Пиши както говориш на човек, когото уважаваш: конкретно, с нормални думи и без празни превъзходни степени. Запази личната интонация, но не използвай „така съм аз“ като оправдание за неяснота. Прочети на глас и замени фразите, които не би казал в разговор. Практическо четиво за кратък рекламен текст е Joseph Sugarman, The Adweek Copywriting Handbook; всяка техника трябва да остане подчинена на истината на офертата."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"„Нашата иновативна система трансформира процеса“ може да стане „Събираме заявките на едно място, за да не ги губиш между чатовете“ — ако това е вярно за услугата."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Коя редакция е най-естествена?","options":[{"id":"a","label":"Добавя „уникален, революционен, невероятен“ към всеки продукт"},{"id":"b","label":"Използва официален текст, който авторът не може да произнесе"},{"id":"c","label":"Казва конкретно какво се случва с обикновени думи"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Копира популярна фраза от чужд създател"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Запиши 30 секунди свободно обяснение. После извади три точни фрази, които звучат като теб, и направи сценарий от тях.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да редактираш репликите така, че да звучат естествено и да пазят фактите","Естественият тон идва от точна мисъл и ясна реч, не от разговорни украшения."],"nextStep":"Изреченията могат да се произнесат; празните претенции са махнати; личният глас не прикрива фактите."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-12","title":"Раздели текста на дъхове и мисли","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да превърнеш писмен текст в реплики, които лесно се произнасят и слушат","hook":"Дългото изречение може да изглежда гладко на екрана, но да звучи като четене.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да превърнеш писмен текст в реплики, които лесно се произнасят и слушат"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Дългото изречение може да изглежда гладко на екрана, но да звучи като четене."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Говорим с кратки мисловни групи, паузи и акцент. Раздели сложната мисъл на причина и следствие; премести уточнение близо до твърдението, което ограничава. Не режи текста механично до еднаква дължина — слушателят трябва да следва смисъла."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"„Сложи телефона по-близо до устата — така гласът ще е по-силен спрямо стаята. Направи тест със слушалки преди записа.“ Две ясни дихателни групи, една причинна връзка."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое изречение е по-лесно за говорене?","options":[{"id":"a","label":"Три съкращения, които зрителят не разбира"},{"id":"b","label":"„Заключи фокуса върху лицето. После премести ръката, за да провериш дали камерата го губи.“"},{"id":"c","label":"Едно изречение от 45 думи с четири уточнения"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Цитат от описанието на продукта без промяна"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Отбележи пауза `/` и ударна дума във всяко изречение от първата чернова. Прочети я на един дъх; пренапиши местата, където губиш смисъл.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да превърнеш писмен текст в реплики, които лесно се произнасят и слушат","Кратките смислови групи намаляват усилието на говорещия и на слушателя."],"nextStep":"Има една мисъл на група; връзката между изреченията е ясна; текстът е пробван на глас."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-13","title":"Изпълни сценария без да звучиш наизуст","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да използваш репетиция, ключови точки и поведение пред камерата за естествено изпълнение","hook":"Много добър текст звучи празно, ако говорещият се опитва да го възпроизведе дума по дума.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш репетиция, ключови точки и поведение пред камерата за естествено изпълнение"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Много добър текст звучи празно, ако говорещият се опитва да го възпроизведе дума по дума."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Преди запис разбери намерението на всеки смислова стъпка. Репетирай в кратки части, отбележи ключовите думи и остави място за естествена интонация. За точни или юридически чувствителни реплики може да е нужен телепромптер; все пак следи зрителския поглед, темпото и произношението."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Обясни една стъпка без сценарий, после сравни с планираната версия. Запази яснотата, добави точните ограничения и махни случайните отклонения."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога е уместно да използваш телепромптер?","options":[{"id":"a","label":"Когато точната формулировка е нужна и говорещият може да я произнесе естествено"},{"id":"b","label":"Винаги, дори за разговорна лична история"},{"id":"c","label":"Само ако авторът не е подготвил съдържанието"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"За да гледаш надолу към екрана"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Запиши една реплика по два начина: дословно от сценария и по три ключови точки. Сравни естественост, точност и време.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да използваш репетиция, ключови точки и поведение пред камерата за естествено изпълнение","Инструментът не заменя подготовката; начинът му на употреба влияе на погледа и гласа."],"nextStep":"Разбираш всеки смислова стъпка; избрал си подходящ метод; фактите остават верни в свободната версия."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-14","title":"Използвай паузи и темпо за смисъл","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да регулираш скоростта според сложността, емоцията и нуждата от разбиране","hook":"Постоянно бързо говорене не е равнозначно на енергично видео.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да регулираш скоростта според сложността, емоцията и нуждата от разбиране"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Постоянно бързо говорене не е равнозначно на енергично видео."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Промени темпото, когато зрителят трябва да види детайл, да сравни или да усети последствие. Пауза може да даде време за обработка; ненужната пауза забавя. Не режи всяко вдишване — звукът на мисълта и ритъмът на изпълнението също носят смисъл."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"В демонстрация на настройка задръж кадъра, докато стойността се сменя. После върни нормално темпо за извод."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога оправдано е да се задържи кадър?","options":[{"id":"a","label":"Когато няма заснет материал за следващата част"},{"id":"b","label":"За да достигнеш произволна дължина"},{"id":"c","label":"Когато зрителят трябва да забележи или сравни нещо"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Когато авторът винаги говори бавно"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Маркирай три места в сценария: ускорение, пауза и кадър, който трябва да остане по-дълго. Обоснови всяко с информацията, която зрителят получава.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да регулираш скоростта според сложността, емоцията и нуждата от разбиране","Темпото следва вниманието, но няма универсален ритъм за всяка сцена."],"nextStep":"Задържането има причина; след него идва нова информация; няма излишно повторение."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-15","title":"Напиши призив, който следва от видеото","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да формулираш едно ясно действие, което е уместно за стойността и готовността на зрителя","hook":"Последните секунди звучат чуждо, когато CTA сменя темата и иска прекалено много.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да формулираш едно ясно действие, което е уместно за стойността и готовността на зрителя"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Последните секунди звучат чуждо, когато CTA сменя темата и иска прекалено много."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Избери каква помощ следва от клипа: запази checklist, виж подробен урок, задай въпрос, сравни условия или направи заявка. Обясни какво ще се случи след клика. Пряката оферта е уместна, когато видеото е дало достатъчен контекст и страницата изпълнява обещанието."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Видео за избор на обектив може да насочи към сравнителна таблица с ограниченията; видеото за самата услуга може да покани към конкретна консултация."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое CTA е най-ясно?","options":[{"id":"a","label":"„Последвай, харесай, коментирай и купи.“"},{"id":"b","label":"„Свали сравнителната таблица; в нея са посочени моделите и ограниченията.“"},{"id":"c","label":"„Действай веднага, преди да изгубиш всичко.“"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"„Линкът решава проблема“, когато линкът не е проверен"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши три CTA за различни ситуации: полезен ресурс, разговор и покупка. За всяко посочи каква информация вече има зрителят.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да формулираш едно ясно действие, което е уместно за стойността и готовността на зрителя","Доверието зависи и от това дали следващата стъпка изпълнява очакването."],"nextStep":"Действието е едно и конкретно; знаеш къде води; обещанието се изпълнява."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-16","title":"Подготви версия за различна готовност на зрителя","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да адаптираш акцента за зрител, който тепърва учи, сравнява решения или е готов за действие","hook":"Един и същ призив може да е полезен за един зрител и преждевременен за друг.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да адаптираш акцента за зрител, който тепърва учи, сравнява решения или е готов за действие"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Един и същ призив може да е полезен за един зрител и преждевременен за друг."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Запази доказаната основна истина, но промени контекста и дълбочината. Начинаещият има нужда от ориентация, сравняващият — от критерии и ограничения, а готовият за действие — от цена, срокове и процес. Не прикривай разликите между тези случаи."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Един и същ курс може да се представи като урок за първи запис, сравнение на подготвени алтернативи или покана към програма с описани изисквания."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какво остава стабилно между версиите?","options":[{"id":"a","label":"Фактите и реалната граница на офертата"},{"id":"b","label":"Претенцията за резултат, за да стане по-продаваща"},{"id":"c","label":"Името на аудиторията, независимо от ситуацията"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Цената и срокът, дори ако се променят"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши три opening + CTA комбинации за една оферта: първо запознанство, сравнение и готовност за записване.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да адаптираш акцента за зрител, който тепърва учи, сравнява решения или е готов за действие","Адаптацията променя приоритета на информацията, не истината за продукта."],"nextStep":"Всяка версия има контекст; обещанията не се разминават; знаеш към кого говори."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-17","title":"Адаптирай сценария към платформата без да го копираш на сляпо","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да промениш кадри, начални контекст и темпо според средата, като запазиш смисъла","hook":"Автоматичното изрязване не прави от един клип три подходящи версии.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да промениш кадри, начални контекст и темпо според средата, като запазиш смисъла"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Автоматичното изрязване не прави от един клип три подходящи версии."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Провери какво вижда човек без звук, кои елементи закриват интерфейсите и колко контекст трябва да добавиш. Запази главното послание, но преработи композицията и началото според вертикален/хоризонтален кадър и очакванията на канала. Техническите правила трябва да се сверят наново."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Демонстрация на интерфейс може да изисква по-голям текст за телефон, а дълъг урок — хоризонтален кадър с четими детайли."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое решение е правилна адаптация?","options":[{"id":"a","label":"Изрязва хоризонтален кадър и приема, че всичко остава четимо"},{"id":"b","label":"Променя самото доказателство, за да пасне на тренда"},{"id":"c","label":"Запазва твърдението, но променя композиция и контекст според гледането"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Оставя интерфейсни елементи върху ключовия текст"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Избери две среди. За всяка направи първи кадър, надпис и CTA. Напиши какво остава същото и какво трябва да се заснеме отделно.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да промениш кадри, начални контекст и темпо според средата, като запазиш смисъла","Адаптацията е част от предварителния сценарий, не само от експорта."],"nextStep":"Проверил си актуалните safe areas; текстът е четим; CTA работи в този канал."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-18","title":"Тествай две версии с една ясна хипотеза","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да сравниш варианти, без да приписваш разликата на грешен фактор","hook":"„Този hook работи“ е прибързан извод, ако сравненията са правени пред различни аудитории.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да сравниш варианти, без да приписваш разликата на грешен фактор"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Този hook работи“ е прибързан извод, ако сравненията са правени пред различни аудитории."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Определи какво проверяваш: разбираемост, задържане до демонстрацията, кликове или отговори. Промени един елемент, доколкото можеш, и пази останалото стабилно. Запиши условията и не обобщавай от малка извадка като универсален закон."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"За две отваряния към един клип използвай еднакъв кадър, оферта, дължина и CTA. Меняй само opening line, после гледай метриката, която съответства на целта."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога сравнението е по-информативно?","options":[{"id":"a","label":"Когато победителят се избира по коментари на приятели"},{"id":"b","label":"Когато една хипотеза е различна, а условията са колкото може по-близки"},{"id":"c","label":"Когато едната версия е 15 секунди, другата 2 минути и CTA-то е различно"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Когато не е записано коя версия е била показана на кого"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Напиши A/B план с две версии, една променлива, целева метрика и ограничение на заключението.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да сравниш варианти, без да приписваш разликата на грешен фактор","Еднаквите условия не гарантират причинност, но правят разликата по-лесна за тълкуване."],"nextStep":"Хипотезата е конкретна; избрал си свързана метрика; записал си лимита на теста."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-19","title":"Редактирай сценария за яснота и време","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да съкратиш сценария, без да махнеш доказателството и нужния контекст","hook":"„Кратко“ не е полезно, ако зрителят вече не разбира как да повтори действието.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да съкратиш сценария, без да махнеш доказателството и нужния контекст"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Кратко“ не е полезно, ако зрителят вече не разбира как да повтори действието."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Прочети на глас и засечи времето си в естествено темпо. Премахни повторение, декоративни въведения и излишни обещания; запази условия, стъпки и резултат. Ако видеото е дълго, раздели тема, а не ускорявай до неразбираем говор."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Вместо три пъти да казваш „приближи микрофона“, кажи веднъж какво да направиш, покажи разстоянието и запиши теста."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое трябва да остане след съкращаване?","options":[{"id":"a","label":"Информация, нужна да се разбере условие, действие и резултат"},{"id":"b","label":"Всички детайли за произхода на автора"},{"id":"c","label":"Три версии на едно обещание"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Пауза, която носи нито смисъл, нито емоция"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Маркирай повторенията в чернова. Запиши дължина преди и след редакция, после провери дали зрителят още може да повтори действието.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да съкратиш сценария, без да махнеш доказателството и нужния контекст","Съкращаването следва функцията на информацията, не произволна цел за секунди."],"nextStep":"Времето е измерено на глас; условията са останали; изводът е ясен без допълнителен контекст."},"required":true,"points":1}]},{"module_id":"s02-m02","lesson_id":"pv02-20","title":"Подготви сценарий, готов за снимане","subtitle":"Практика за сценарий, изпълнение и редакция","estimated_minutes":16,"objective":"да предадеш сценарий с текст, кадри, доказателства и начин за проверка","hook":"Хубав текст не е снимачен документ, докато екипът не разбира какво да заснеме.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да предадеш сценарий с текст, кадри, доказателства и начин за проверка"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Хубав текст не е снимачен документ, докато екипът не разбира какво да заснеме."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Включи работно заглавие, аудитория, цел, точни реплики, смислови стъпки, кадър или демонстрация към всяко ключово твърдение, източник/разрешения и CTA. Добави бележки за произношение и дубъл. Остави решенията, които зависят от камерата, за Модул 3, но отбележи какво трябва да се види."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"При твърдение за разлика между два кадъра посочи реда, еднаквите условия, надписите и как ще се избегне различна експозиция."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое прави сценария готов за екип?","options":[{"id":"a","label":"Само звучно заглавие и крайна реплика"},{"id":"b","label":"Списък с монтажни ефекти без цел"},{"id":"c","label":"Изпълним ред, нужните кадри, проверени твърдения и ясни условия"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Текст, който никой не е прочел на глас"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Прочети сценария на глас и запиши времето. Посочи една реплика, която още звучи написана, и редактирай я така, че да я кажеш естествено.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"quality_gate","type":"checklist","title":"Самопроверка преди предаване","content":{"items":[{"id":"check-1","text":"Началото обещава това, което видеото показва.","required":true},{"id":"check-2","text":"Сценарият има ясен ред и не се отклонява от една основна идея.","required":true},{"id":"check-3","text":"Твърденията имат източник, демонстрация или ясно обозначено ограничение.","required":true},{"id":"check-4","text":"Текстът е прочетен на глас и времето е проверено.","required":true},{"id":"check-5","text":"Следващото действие е конкретно и уместно.","required":true}]},"required":true,"points":2},{"key":"submission","type":"submission","title":"Предай работата си","content":{"prompt":"Качи сценария или сподели връзка към документа и пробния запис. Включи две версии на началото, смисловите стъпки, кадър или доказателство за всяко основно твърдение, подходящ призив и проверено време.","accept":"link,file"},"required":true,"points":4},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да предадеш сценарий с текст, кадри, доказателства и начин за проверка","Подготовката намалява догадките, но оставя място за естествено изпълнение."],"nextStep":"Посланието е едно; всяко важно твърдение има кадър или източник; времето е проверено."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-01","title":"Избери кадровата честота за движението и доставката","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да избереш кадрова честота според движението, желаното възпроизвеждане и възможностите на устройството","hook":"„24 срещу 60“ няма смисъл без въпрос какво се движи и къде ще се гледа.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избереш кадрова честота според движението, желаното възпроизвеждане и възможностите на устройството"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„24 срещу 60“ няма смисъл без въпрос какво се движи и къде ще се гледа."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Кадровата честота описва колко кадъра се записват или показват за секунда. За нормална скорост избери стойност, която устройството записва надеждно и която съвпада с монтажния проект/доставката. Забавен кадър изисква по-висока честота, заснета предварително; проверявай светлинното трептене и актуалните настройки на устройството."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Говорещ човек в стая и бързо движение на спортна топка имат различни нужди. Ако снимаш 60 fps, но не забавяш кадъра, файлът не става автоматично „по-кинематографичен“."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Как получаваш истински материал за забавен кадър?","options":[{"id":"a","label":"Увеличаваш резолюцията след снимане"},{"id":"b","label":"Записваш действието с по-висока кадрова честота и съзнателно го забавяш"},{"id":"c","label":"Избираш 60 fps само в настройките за експорт"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Оставяш камерата на Auto и приемаш резултата"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Заснеми едно движение в две налични честоти. Монтирай ги на еднаква дължина и запиши как се различават плавността, размазването и размерът на файла.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да избереш кадрова честота според движението, желаното възпроизвеждане и възможностите на устройството","Забавянето изисква повече кадри, заснети в реално време; експортът не може да възстанови липсващо движение."],"nextStep":"Проверил си наличните честоти; знаеш дали кадърът ще е нормален или забавен; проектът е съвместим."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-02","title":"Настрой затвора според движението","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да разпознаваш как времето на експонация влияе на размазването при движение","hook":"Стоп-кадърът е рязък, но всяко движение в готовото видео оставя неестествена следа.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да разпознаваш как времето на експонация влияе на размазването при движение"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Стоп-кадърът е рязък, но всяко движение в готовото видео оставя неестествена следа."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Затворът определя колко дълго сензорът събира светлина за всеки кадър. По-дълго време обикновено дава повече размазване; по-кратко — по-рязко движение, но често по-малко светлина. За естествено движение в 24/25/30 fps, приблизително двойно по-дълга скорост от кадровата честота е отправна точка, не закон. При ярка светлина ND може да помогне да я запазиш."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"При 25 fps 1/50 s е типична начална настройка. Ако снимаш спорт или много бързи движения, може да избереш по-кратка експонация и по-стегнат вид."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Защо често се използва затвор около два пъти кадровата честота?","options":[{"id":"a","label":"Като практична отправна точка за естествено размазване при нормално движение"},{"id":"b","label":"Защото камерата иначе не може да фокусира"},{"id":"c","label":"Защото така файлът винаги става по-малък"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Защото това е задължително правило за всяка сцена"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Снимай една и съща ръчна жестова демонстрация с две налични стойности на затвора. Не променяй честотата; сравни движението и експозицията.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да разпознаваш как времето на експонация влияе на размазването при движение","Това е конвенционална база за естественото усещане, но художествената задача може да изисква друг избор."],"nextStep":"Кадровата честота остава същата; виждаш промяна в движението; проверил си трептене и експозиция."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-03","title":"Експонирай чисто преди да вдигаш ISO","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да намалиш шум и загуба на детайл чрез правилна експозиция и разумен избор на светлина","hook":"Подекспонираното лице не става чисто само защото го изсветлиш в монтажа.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да намалиш шум и загуба на детайл чрез правилна експозиция и разумен избор на светлина"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Подекспонираното лице не става чисто само защото го изсветлиш в монтажа."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"ISO/gain влияе на усилването на сигнала и на видимия шум; точната реализация зависи от камерата. Първо подреди светлината и експозицията, после вдигни ISO само колкото трябва. Следи както сенките, така и светлите участъци: клипнатите детайли не се връщат надеждно при корекция."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"В стая с малко светлина премести говорещия към по-светла страна на прозореца, вместо веднага да повишиш ISO до максимум. Направи тест и гледай тъмните области."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Коя промяна обикновено е по-добра преди силно усилване на ISO?","options":[{"id":"a","label":"Изсветли файла силно след записа"},{"id":"b","label":"Сложи цифрово увеличение"},{"id":"c","label":"Подобри наличната светлина или позицията спрямо нея"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Смени баланса на бялото, за да премахнеш шума"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Заснеми един и същ кадър при наличната светлина и след като преместиш източника/субекта. Сравни лицето, сенките и шума на екрана, където ще се гледа.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да намалиш шум и загуба на детайл чрез правилна експозиция и разумен избор на светлина","Повече полезен светлинен сигнал често дава по-чист материал; балансът на бялото не премахва шум от недоекспониране."],"nextStep":"Лицето е достатъчно осветено; светлите детайли не са изгорели; гледал си записа, а не само индикатора."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-04","title":"Дръж фокуса върху важното","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да избираш между автофокус, заключен фокус и ръчен фокус според сцената","hook":"Камерата следи ръката зад продукта, докато зрителят трябва да вижда лицето.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш между автофокус, заключен фокус и ръчен фокус според сцената"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Камерата следи ръката зад продукта, докато зрителят трябва да вижда лицето."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"За говореща глава автоматичното разпознаване на лице/око често е удобно, но проверявай дали системата не прескача към фон или предмет. Заключи фокус, когато разстоянието е постоянно; използвай ръчен фокус, когато автоматиката се колебае или снимаш повторяемо движение. Тествай преди дубъла."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Постави знак на мястото, където ще застане участникът. Направи тест, протегни ръка към предмет и виж дали камерата се прехвърля неволно."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога заключеният фокус е разумен избор?","options":[{"id":"a","label":"Когато не си проверил тестовия запис"},{"id":"b","label":"Когато субектът остава на предварително отбелязано разстояние"},{"id":"c","label":"Когато субектът тича към и от камерата"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Когато фокусът трябва да преминава между обекти"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Заснеми 10-секунден тест с лице и един предмет в кадъра. Провери по време на възпроизвеждането къде камерата е държала фокуса.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да избираш между автофокус, заключен фокус и ръчен фокус според сцената","Твърдото фиксиране е стабилно при постоянна дистанция; при движение трябва да се следи фокусът."],"nextStep":"Очите/детайлът са ясни; системата не прескача; тестът е гледан на цял екран."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-05","title":"Заключи баланса на бялото за последователни цветове","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да поддържаш постоянен цвят на кожата и предметите между дублите","hook":"Камерата сменя топлия и студения тон, когато човек се движи през различно осветени места.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да поддържаш постоянен цвят на кожата и предметите между дублите"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Камерата сменя топлия и студения тон, когато човек се движи през различно осветени места."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Балансът на бялото компенсира оттенъка на източника на светлина. Auto WB може да се променя между кадри, особено при смесена светлина или голям цветен предмет в кадъра. Използвай preset или ръчно измерване, ако устройството го позволява; направи тест с неутрален обект. Най-лесният вариант често е да премахнеш смесените източници."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Лице до прозорец с топла настолна лампа може да изглежда различно в кадър и монтаж. Изключи единия източник или реши кой оттенък искаш да води."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Защо е полезно да заключиш WB в една сцена?","options":[{"id":"a","label":"Предотвратява неволни цветови скокове между дублите"},{"id":"b","label":"Намалява размера на файла"},{"id":"c","label":"Размазва фона по-силно"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Прави всеки източник на светлина с еднакъв цвят"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Заснеми един кадър с Auto WB и един със заключен баланс в същата стая. Сравни двата, докато ръката влиза в кадър.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да поддържаш постоянен цвят на кожата и предметите между дублите","Заключването пази постоянство, но смесената светлина все пак може да има различни оттенъци."],"nextStep":"WB е избран за реалния източник; камерата не сменя оттенъка; кожата изглежда естествено."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-06","title":"Подготви светлина, фон и звук в стаята","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да използваш наличната светлина и място за четим образ и разбираем глас","hook":"Камерата записва всичко в стаята: плоска светлина, претрупан фон и ехо също влизат в кадъра.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш наличната светлина и място за четим образ и разбираем глас"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Камерата записва всичко в стаята: плоска светлина, претрупан фон и ехо също влизат в кадъра."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Постави основната светлина леко встрани от лицето, разсей я, ако е твърда, и отдели говорещия от фона, когато пространството позволява. Огледай фона за ярки петна и случайни предмети. За звук приближи микрофона/телефона, намали източника на шум и прослушай пробата със слушалки. За системна работа с изображението и камерата може да използваш Blain Brown, Cinematography: Theory and Practice, като проверяваш всеки избор в реалната си локация."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"До прозорец застани под ъгъл, а не с яркия прозорец право зад главата. Плътна завеса и меки предмети в стаята могат да намалят отраженията на гласа."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Коя промяна най-пряко помага на гласа да бъде разбираем?","options":[{"id":"a","label":"Изостряне на картината"},{"id":"b","label":"Повишаване на наситеността"},{"id":"c","label":"Преместване на микрофона по-близо и тест със слушалки"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Добавяне на музика върху неразбираем диалог"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Направи три теста от една локация: промени посоката на светлината, позицията спрямо фона и разстоянието до микрофона. Отбележи кой фактор подобри какво.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да използваш наличната светлина и място за четим образ и разбираем глас","Близостта до микрофона често подобрява отношението на гласа към околния шум."],"nextStep":"Проверил си фон и източник на светлина; гласът е прослушан; тестът е записан от реалната позиция."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-07","title":"Запази файл, който отговаря на целевия екран","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да съчетаеш резолюция, кадрова честота, формат и качество при експортиране","hook":"„Най-висок bitrate“ не поправя фокус, светлина или грешен формат.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да съчетаеш резолюция, кадрова честота, формат и качество при експортиране"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"„Най-висок bitrate“ не поправя фокус, светлина или грешен формат."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Запази оригиналния запис и направи отделен експорт за конкретната доставка. Съпостави резолюцията и честотата с проекта, избери широко поддържан контейнер/кодек и използвай актуалните указания на платформата. Bitrate е поток от данни, не оценка на творческо качество. Log профил ползвай само ако камерата го поддържа и имаш последователен цветови workflow."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Експорт с излишно висока резолюция увеличава файла, но не създава детайл, който липсва в оригинала. При Log без цветова корекция изображението може да изглежда плоско."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какво трябва да определя настройките за експорт?","options":[{"id":"a","label":"Само размерът на паметта в телефона"},{"id":"b","label":"Целевият канал, оригиналният материал и актуалните му изисквания"},{"id":"c","label":"Максималният bitrate, независимо от източника"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Пресетът, който е избран по подразбиране"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Експортирай тест от 10 секунди в целевия размер и честота. Провери четимост на текста, синхрон на звук, черни ленти и размер на файла.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да съчетаеш резолюция, кадрова честота, формат и качество при експортиране","Експортът трябва да съвпада с източника и начина на доставка, а не да гони абстрактен максимум."],"nextStep":"Съхранил си оригинала; проверил си актуалните изисквания; прегледал си крайния тестов файл."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-08","title":"Кадрирай за вертикално и хоризонтално гледане","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да планираш композицията така, че основният смисъл да остане видим в избрания формат","hook":"Изрязаният кадър може да отреже не само рамката, а и важната информация.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да планираш композицията така, че основният смисъл да остане видим в избрания формат"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Изрязаният кадър може да отреже не само рамката, а и важната информация."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Избери формат преди снимане, когато можеш. Ако материалът трябва да работи в повече от едно съотношение, дръж важните елементи в безопасната зона или запиши отделни кадри. Оставяй място за заглавия и интерфейсни елементи; сверявай текущите safe areas за конкретния канал."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Широк кадър с две лица може да не позволи читаем вертикален crop. Заснеми отделен близък план или премести субектите."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога е по-добре да снимаш допълнителен вертикален кадър?","options":[{"id":"a","label":"Когато crop премахва важен субект, текст или действие"},{"id":"b","label":"Когато съотношението изглежда модерно"},{"id":"c","label":"Когато файлът е прекалено малък"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Когато монтажът може да добави липсващите пиксели"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Нарисувай 9:16 и 16:9 рамки около една сцена. Отбележи какво отпада и какъв отделен кадър ти трябва.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да планираш композицията така, че основният смисъл да остане видим в избрания формат","Изрязването не може да възстанови съдържание, което не е било в кадъра."],"nextStep":"Форматът избран преди снимане; важният текст далеч от UI; има отделен кадър за вертикал при нужда."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-09","title":"Различавай фокусно разстояние и перспектива","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да избираш позиция и обектив според пространството и характера на кадъра","hook":"Близкият портрет с широкоъгълен обектив може да преувеличи носа и да направи лицето непривично.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш позиция и обектив според пространството и характера на кадъра"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Близкият портрет с широкоъгълен обектив може да преувеличи носа и да направи лицето непривично."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Фокусното разстояние променя зрителния ъгъл. Перспективата основно се променя, когато местиш камерата спрямо субекта: близо изглеждат различно относителните размери на близки и далечни части. Не обвинявай само обектива; избери дистанция, после кадрирай и провери деформацията."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Снимай лицето от една и съща позиция с две фокусни настройки, после приближи камерата, за да възстановиш размера. Ще видиш, че дистанцията също е променила отношението между лицето и фона."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое най-силно променя перспективата на портрета?","options":[{"id":"a","label":"Смяна на файла с по-висок bitrate"},{"id":"b","label":"Само експозицията"},{"id":"c","label":"Промяна на дистанцията между камерата и лицето"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Добавяне на crop без промяна на ракурса"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Заснеми два портрета: широк отблизо и по-дълъг ъгъл от по-далеч. Сравни пропорциите, фон и пространство.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да избираш позиция и обектив според пространството и характера на кадъра","Промяната на ракурса от различна дистанция променя отношението на близките и далечните части."],"nextStep":"Субектът не е изкривен; фокусното разстояние пасва на стаята; фонът е избран съзнателно."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-10","title":"Отдели субекта от фона без софтуерен трик","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да използваш разстояние, кадриране и светлина за по-ясни планове","hook":"Портретният режим прави косата на човек назъбена, а фонът пак остава разсейващ.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш разстояние, кадриране и светлина за по-ясни планове"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Портретният режим прави косата на човек назъбена, а фонът пак остава разсейващ."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Отдалечи субекта от стената, избери подходящо фокусно разстояние и създай различие в яркост или цвят. Дълбочината на рязкост зависи от камерата, фокусното разстояние, разстоянието и диафрагмата, когато е налична. Проверявай софтуерното размазване за грешни ръбове и не жертвай важната среда."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"В тясна стая премести стола на метър от стената и добави лампа отстрани; може да стане по-ясно, дори без размазан фон."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какъв е най-надеждният първи ход за естествено отделяне от фона?","options":[{"id":"a","label":"Приближи широкия обектив до лицето"},{"id":"b","label":"Увеличи разстоянието между субекта и фона"},{"id":"c","label":"Включи портретен филтър без проверка"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Избери най-тъмната експозиция"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Направи три версии на една сцена: субект до стената, отдалечен от стената и с променена светлина. Запиши кое разделя плановете най-добре.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да използваш разстояние, кадриране и светлина за по-ясни планове","Физическото разстояние и светлинното разграничение са контролируеми; филтърът може да създаде артефакти."],"nextStep":"Плановете различават субекта; ръбовете са чисти; фонът не конкурира лицето."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-11","title":"Използвай ND филтър, когато светлината е прекалено силна","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да разпознаеш нөхцөлата, в която неутрално-сив филтър помага да запазиш затвора и диафрагмата","hook":"На обяд снимаш движение с намерения вид, но светлината кара камерата да избере прекалено кратка експозиция.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да разпознаеш нөхцөлата, в която неутрално-сив филтър помага да запазиш затвора и диафрагмата"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"На обяд снимаш движение с намерения вид, но светлината кара камерата да избере прекалено кратка експозиция."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"ND филтърът намалява количеството светлина, без да променя композиционния замисъл. Полезен е навън, когато искаш да пазиш определен затвор или малка дълбочина на рязкост. Проверявай цветен оттенък, неравномерност при силно затъмняване и съвместимост с обектива. Не замества сенник, отражател или осветление."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"За говорещ пред прозорец ND може да помогне при ярък ден, ако затворът и ISO вече са на желаните стойности. На сянка филтърът може само да направи кадъра по-тъмен."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Каква е основната функция на ND филтъра?","options":[{"id":"a","label":"Намалява светлината, която влиза в обектива"},{"id":"b","label":"Прави автофокуса автоматично по-точен"},{"id":"c","label":"Премахва всички отражения като поляризатор"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Добавя резолюция към сензора"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Заснеми един клип на ярка светлина с ND и без него. Запиши експозиция, затвор, ISO и видимия цветови оттенък.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да разпознаеш нөхцөлата, в която неутрално-сив филтър помага да запазиш затвора и диафрагмата","ND контролира количеството светлина; различните филтри могат да имат цветови/оптични странични ефекти."],"nextStep":"Използваш ND при достатъчно светлина; не бъркаш го с поляризатор; проверил си цветовете."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-12","title":"Пази посоката на действие в монтажа","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да използваш оста и правилото на 180° за ясна пространствена ориентация","hook":"Двама души сменят страните си през монтажния скок, въпреки че никой не е помръднал.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш оста и правилото на 180° за ясна пространствена ориентация"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Двама души сменят страните си през монтажния скок, въпреки че никой не е помръднал."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Начертай мислена линия между говорещите или по посоката на движение. Дръж камерата от една страна, за да останат погледите и движението консистентни. Пресичането е възможно, ако покажеш самото движение или вмъкнеш неутрален кадър, който преориентира зрителя. Правилото е средство за четимост, не забрана. За задълбочаване по темата виж The Five C''s of Cinematography, където камерата, монтажът и ориентацията се разглеждат като част от една последователност."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"В интервю A гледа вдясно от кадъра, а B — вляво. Ако снимаш B от същата страна, посоката на погледите остава разбираема."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Какво помага при преминаване през оста?","options":[{"id":"a","label":"Сменяш ракурс незабелязано по средата на реплика"},{"id":"b","label":"Обръщаш кадъра огледално, без проверка на надписи"},{"id":"c","label":"Показваш преминаването или използваш неутрален кадър за преориентиране"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Преместваш само микрофона"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Нарисувай ос за интервю или движение. Отбележи три позиции на камерата от една страна и една безопасна преходна позиция.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да използваш оста и правилото на 180° за ясна пространствена ориентация","Преходният кадър показва къде сме и позволява зрителя да преизгради географията."],"nextStep":"Посоката на поглед е последователна; осевите кадри са отбелязани; преходът е заснет, ако сменяш страна."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-13","title":"Използвай третините като насока, не закон","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да разположиш субект и поглед така, че кадърът да подкрепя сцената","hook":"Лице точно в пресечната точка не е автоматично по-добър кадър.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да разположиш субект и поглед така, че кадърът да подкрепя сцената"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Лице точно в пресечната точка не е автоматично по-добър кадър."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Мрежата на третините може да помогне за баланс и място за поглед, но централната композиция често е по-ясна или по-силна. Решавай според намерението, фона, надписите и следващия кадър. Провери headroom, eye line и дали лицето е удобно разположено на телефона."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Интервю с поглед към външния интервюиращ може да остави място пред лицето; директен апел към камерата може да бъде въздействащ в центъра."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога централният кадър може да е силно решение?","options":[{"id":"a","label":"Само когато снимаш без звук"},{"id":"b","label":"Когато искаш директност, симетрия или графична стабилност"},{"id":"c","label":"Никога — правилото забранява центъра"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Когато камерата има мрежа на екрана"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Заснеми една реплика в център и по третини. Сравни яснотата, празното пространство и връзката с погледа.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да разположиш субект и поглед така, че кадърът да подкрепя сцената","Композиционните насоки служат на идеята; няма едно място, подходящо за всяка сцена."],"nextStep":"Знаеш къде гледа субектът; headroom е умишлен; кадърът работи с надписите."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-14","title":"Насочи погледа с линии и форми","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да използваш видимите линии, без да отклоняваш вниманието от главния субект","hook":"Пътеката води погледа право извън кадъра, вместо към действието.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш видимите линии, без да отклоняваш вниманието от главния субект"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Пътеката води погледа право извън кадъра, вместо към действието."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Линии, диагонали, повторения и контраст могат да организират кадъра. Провери къде започват и къде завършват, дали водят към важния елемент и дали създават нежелани допирателни с ръб на глава или обект. Ако линията води навън, промени позицията или я прекъсни с фокусен елемент."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Ръбът на масата може да насочи към продукта. Ако свършва в ярък предмет зад него, зрителят може да гледа там вместо към демонстрацията."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Как оценяваш водеща линия?","options":[{"id":"a","label":"Проследяваш началото и края и гледаш накъде отива вниманието"},{"id":"b","label":"Избираш всяка диагонална линия като добра"},{"id":"c","label":"Добавяш стрелка във всеки кадър"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Снимаш само хоризонтални линии"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Намери три линии в локацията си. Заснеми по един кадър така, че всяка да води към субекта, и един контрапример.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да използваш видимите линии, без да отклоняваш вниманието от главния субект","Линията е полезна, когато управлява визуалния път към важната информация."],"nextStep":"Пътят на окото е предвиден; фонът не краде акцента; линията няма случайно продължение през субекта."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-15","title":"Остави място за поглед и графика","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да използваш празното пространство така, че да балансира кадъра и да побере нужната информация","hook":"Надписът закрива демонстрацията, защото кадърът е бил композиран само за красив screenshot.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да използваш празното пространство така, че да балансира кадъра и да побере нужната информация"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Надписът закрива демонстрацията, защото кадърът е бил композиран само за красив screenshot."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Negative space е площ без доминиращ детайл, която може да даде въздух, баланс или място за текст. Не е задължително да стои пред лицето; избери мястото според посоката на поглед, действието и интерфейса. Не запълвай го, ако празнотата поддържа емоцията."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Говорещ, разположен вдясно и гледащ наляво, може да остави свободно пространство вляво за кратък надпис — стига платформеният интерфейс да не го закрива."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Къде да оставиш свободно място за надпис?","options":[{"id":"a","label":"Винаги над главата"},{"id":"b","label":"Само в центъра на лицето"},{"id":"c","label":"Там, където не закрива действие и остава видимо в целевия интерфейс"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"В която и да е празна част без проверка"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Кадрирай една реплика с място отляво и отдясно. Постави примерен надпис и провери четимостта на телефона.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да използваш празното пространство така, че да балансира кадъра и да побере нужната информация","Свободното място има функция, но трябва да се съобрази с поглед и UI."],"nextStep":"Погледът води към кадъра; надписът е четим; важният елемент не е покрит."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-16","title":"Използвай преден, среден и заден план","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да добавиш дълбочина и контекст, без да претрупаш кадъра","hook":"Кадърът изглежда плосък, защото камерата вижда само стена и лице.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да добавиш дълбочина и контекст, без да претрупаш кадъра"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Кадърът изглежда плосък, защото камерата вижда само стена и лице."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Раздели сцената на преден, среден и заден план. Премести субекта от стената, намери детайл отпред, който не краде вниманието, и използвай фон, който помага да разберем мястото. Дълбочината може да се създаде с разстояние и композиция, не само с размазан фон. Bruce Block, The Visual Story, и Blain Brown, Cinematography: Theory and Practice, дават полезен речник за пространство, планове и визуален акцент."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Интервю в работилница може да има разфокусиран инструмент отпред, лицето в средния план и станцията на заден план — ако трите нива подкрепят обяснението."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Коя е основната функция на трите плана?","options":[{"id":"a","label":"Да направят всяка камера фокусираща по-бързо"},{"id":"b","label":"Да създадат пространствена дълбочина и да дадат контекст"},{"id":"c","label":"Да скрият погрешен баланс на бялото"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Да накарат зрителя да гледа само предния план"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Направи две версии на един кадър: до стената и с три различими плана. Обясни какво добавя всеки план.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да добавиш дълбочина и контекст, без да претрупаш кадъра","Слоевете правят пространството разбираемо, стига най-важният план да остане ясен."],"nextStep":"Има различими дистанции; субектът отделен; предният план не закрива критични детайли."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-17","title":"Движи камерата само когато движението помага","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да избираш статичен кадър, панорама, наклон или проследяване според действието","hook":"Камерата се движи пет секунди по празна стена и нищо ново не научаваме.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да избираш статичен кадър, панорама, наклон или проследяване според действието"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Камерата се движи пет секунди по празна стена и нищо ново не научаваме."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Движението може да разкрие, проследи, свърже или промени отношението към субекта. Започни и завърши движението устойчиво; провери дали го може камерата/операторът и дали фокусът остава. Ако движението не добавя информация, статичен кадър често е по-ясен."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Проследи ръка, която сглобява продукт; движението следва самото действие. Панорамиране през празни предмети няма същата причина."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога движението на камерата е оправдано?","options":[{"id":"a","label":"Когато разкрива или следи важна информация"},{"id":"b","label":"Когато операторът скучае"},{"id":"c","label":"Когато кадърът изглежда твърде стабилен"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"За да запълниш пауза без нов материал"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Заснеми статичен кадър и едно мотивирано движение към същото действие. Запиши коя нова информация се появява и кога.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да избираш статичен кадър, панорама, наклон или проследяване според действието","Движението трябва да има точка на начало и цел, които подкрепят сцената."],"nextStep":"Движението е плавно; има причина; фокусът и кадрирането остават контролирани."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-18","title":"Използвай рамка в рамката с ясна причина","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да поставиш субекта в естествена рамка, която добавя контекст или фокус","hook":"Арка пред лицето може да изглежда като пречка, ако не добавя нищо към сцената.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да поставиш субекта в естествена рамка, която добавя контекст или фокус"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Арка пред лицето може да изглежда като пречка, ако не добавя нищо към сцената."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Врати, прозорци, огледала и други естествени форми могат да ограничат вниманието и да покажат връзка между пространства. Следи рамката да не пресича лице/тяло и да не отвлича от действието. Избери светлина, фокус и контраст така, че субектът вътре да е четим."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Готвач може да бъде видян през прохода към кухнята, защото това установява мястото. Ако рамката е тъмна и поглъща лицето, премести камерата."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кога естествената рамка работи?","options":[{"id":"a","label":"Когато закрива половината от важния предмет"},{"id":"b","label":"Когато е винаги симетрична"},{"id":"c","label":"Когато насочва вниманието или обяснява пространствената връзка"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Когато прави фона по-сложен"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Намери две рамки в пространството. Заснеми вариант с и без тях и напиши какво смислово добавят.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да поставиш субекта в естествена рамка, която добавя контекст или фокус","Естествената рамка е композиционен елемент само ако поддържа четимост и смисъл."],"nextStep":"Субектът е четим; рамката има причина; светлината не създава нежелан силует."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-19","title":"Избери визуален баланс според усещането","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да сравниш симетричен и асиметричен баланс според намерението","hook":"Центрираната симетрия може да звучи официално; асиметрията може да даде движение, но и да разсее.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да сравниш симетричен и асиметричен баланс според намерението"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Центрираната симетрия може да звучи официално; асиметрията може да даде движение, но и да разсее."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Симетрията често създава ред и устойчивост; асиметрията може да създаде напрежение, посока или интимност. Това са възможни асоциации, не универсална емоционална граматика. Балансирай визуална тежест чрез размер, светлина, цвят и свободно пространство."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Директно обръщение към камерата може да спечели от център. История за неизвестност може да използва празно пространство и субект извън центъра."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Как сравняваш баланса?","options":[{"id":"a","label":"Считаш центъра за техническа грешка"},{"id":"b","label":"Гледаш къде е визуалната тежест и тестваш дали тя подкрепя сцената"},{"id":"c","label":"Избираш асиметрия за всяко видео"}]},"evaluation":{"correct":"b"},"feedback":{"explanation":"Местиш субекта без да провериш фона"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Заснеми една фразу симетрично и асиметрично. Покажи ги на двама зрители и попитай какво първо забелязват, без да подсказваш отговора.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да сравниш симетричен и асиметричен баланс според намерението","Композицията въздейства според контекста и елементите, не чрез твърди обещания за емоция."],"nextStep":"Първият поглед отива към важния елемент; балансът пасва на тона; зрителският тест е неутрален."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-20","title":"Прекадрирай композицията за вертикален екран","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да запазиш четимост и визуална йерархия при тесен вертикален кадър","hook":"Хоризонталната линия се прекъсва при crop и вече не води погледа.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да запазиш четимост и визуална йерархия при тесен вертикален кадър"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Хоризонталната линия се прекъсва при crop и вече не води погледа."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Вертикалният формат променя пространството: подчертава височина, сгъстява групи и ограничава периферни елементи. Пренареди субект, фон и текст; ако се губи смисълът, заснеми отделен кадър. Остави ключови елементи извън местата, покрити от актуалния интерфейс."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"Дълга ограда може да работи диагонално, ако кадрираш така, че линията води към лицето. При тесен crop заснеми нов ракурс вместо да разчиташ на цялата ограда."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Защо автоматичният crop често е недостатъчен?","options":[{"id":"a","label":"Може да премахне субекта или да прекъсне визуалната посока"},{"id":"b","label":"Защото вертикалните кадри не поддържат звук"},{"id":"c","label":"Защото всяка платформа премахва хоризонтални линии"}]},"evaluation":{"correct":"a"},"feedback":{"explanation":"Защото камерата не може да фокусира във вертикално положение"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Превърни един хоризонтален storyboard във вертикален. Отметни кадрите, които трябва да се снимат отделно и мястото на UI.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да запазиш четимост и визуална йерархия при тесен вертикален кадър","Форматът променя композицията; повторното кадриране е творческо решение."],"nextStep":"Ключовият субект остава видим; текстът е в safe area; отделните кадри са планирани."},"required":true,"points":1}]},{"module_id":"s02-m03","lesson_id":"pv03-21","title":"Заснеми последователност, която доказва умението ти","subtitle":"Кадър, звук и техническа подготовка","estimated_minutes":17,"objective":"да предадеш кратко видео с последователна композиция, проверени настройки и ясна цел","hook":"Технически красиви кадри не образуват завършено видео, ако посоката, звукът и смисълът се разминават.","change_note":"Обновена практическа програма v3: запазени са ID-тата; старите версии остават за история.","blocks":[{"key":"objective","type":"objective","title":"Какво ще можеш","content":{"body":"да предадеш кратко видео с последователна композиция, проверени настройки и ясна цел"},"required":true,"points":1},{"key":"hook","type":"hook","title":"Защо това е важно","content":{"body":"Технически красиви кадри не образуват завършено видео, ако посоката, звукът и смисълът се разминават."},"required":true,"points":1},{"key":"core","type":"rich_text","title":"Принцип и метод","content":{"body":"Направи серия от кадри, в която всеки има функция: установява място, показва действие, дава детайл, доказва разлика или завършва мисъл. Провери fps и затвор за движението, експозиция, фокус, WB, звук, посока по оста, формат и експорт. Включи тест, резервен кадър и лист с настройките."},"required":true,"points":1},{"key":"example","type":"example","title":"Пример от работа","content":{"body":"За кратко демо: установяващ кадър на работното място, среден план на действието, детайл на резултата, реакция и финален CTA. Не са нужни 10 различни ъгъла, ако петте са ясни."},"required":true,"points":1},{"key":"knowledge_check","type":"quiz","title":"Провери разбирането","content":{"question":"Кое доказва готовност за базова снимачна задача?","options":[{"id":"a","label":"Десет случайни кадъра и най-скъпото оборудване"},{"id":"b","label":"Силна музика върху неразбираем глас"},{"id":"c","label":"Четима последователност с проверени технически условия и обяснена цел"}]},"evaluation":{"correct":"c"},"feedback":{"explanation":"Ефекти, които прикриват грешната посока"},"scoring":{"mode":"single_choice"},"required":true,"points":2},{"key":"practice","type":"practical_response","title":"Направи го върху своя проект","content":{"prompt":"Гледай клипа веднъж без звук и веднъж със слушалки. Опиши по един проблем в композицията и техниката и избери коя корекция ще направиш първо.\n\nВ отговора опиши какво направи, какъв резултат видя и какво ще промениш следващия път.","minLength":60,"placeholder":"Опиши решението си и как ще го провериш."},"required":true,"points":2},{"key":"quality_gate","type":"checklist","title":"Самопроверка преди предаване","content":{"items":[{"id":"check-1","text":"Кадровата честота и затвор съвпадат с движението и замисъла.","required":true},{"id":"check-2","text":"Фокусът, експозицията и балансът на бялото остават под контрол.","required":true},{"id":"check-3","text":"Гласът е прослушан и разбираем.","required":true},{"id":"check-4","text":"Кадрите следват целта и пазят пространствената посока.","required":true},{"id":"check-5","text":"Експортът е прегледан в целевия формат.","required":true}]},"required":true,"points":2},{"key":"submission","type":"submission","title":"Предай работата си","content":{"prompt":"Качи финалния клип или сподели достъпна връзка към клип и настройките. Включи кратък лист с цел, кадрова честота, затвор или експозиция, фокус, баланс на бялото, звук и формат. Не включвай чуждо лице или лични данни без разрешение.","accept":"link,file"},"required":true,"points":4},{"key":"summary","type":"summary","title":"Запомни и продължи","content":{"takeaways":["да предадеш кратко видео с последователна композиция, проверени настройки и ясна цел","Кадърът и техническите настройки трябва да работят за една и съща история."],"nextStep":"Клипът има начало и край; звукът е прослушан; кадрите са последователни; самопроверка е приложена."},"required":true,"points":1}]}]'::jsonb)
  LOOP
    SELECT id, published_version_id
      INTO lesson_uuid, previous_version_uuid
      FROM public.academy_lessons
      WHERE module_id = lesson_spec->>'module_id'
        AND lesson_id = lesson_spec->>'lesson_id'
      FOR UPDATE;

    IF lesson_uuid IS NULL THEN
      INSERT INTO public.academy_lessons(module_id, lesson_id, status, created_at, updated_at)
      VALUES (lesson_spec->>'module_id', lesson_spec->>'lesson_id', 'draft', now(), now())
      RETURNING id INTO lesson_uuid;
      previous_version_uuid := NULL;
    END IF;

    SELECT coalesce(max(version_number), 0) + 1
      INTO new_version_number
      FROM public.academy_lesson_versions
      WHERE academy_lesson_id = lesson_uuid;

    INSERT INTO public.academy_lesson_versions(
      academy_lesson_id, version_number, origin_version_id, title, subtitle, duration,
      objective, hook, estimated_minutes, source_kind, change_note, created_by
    )
    VALUES (
      lesson_uuid,
      new_version_number,
      previous_version_uuid,
      lesson_spec->>'title',
      coalesce(lesson_spec->>'subtitle', ''),
      (lesson_spec->>'estimated_minutes') || ' минути',
      lesson_spec->>'objective',
      lesson_spec->>'hook',
      (lesson_spec->>'estimated_minutes')::integer,
      'editor',
      lesson_spec->>'change_note',
      NULL
    )
    RETURNING id INTO new_version_uuid;

    FOR block_spec IN
      SELECT value, ordinality
      FROM jsonb_array_elements(lesson_spec->'blocks') WITH ORDINALITY
      ORDER BY ordinality
    LOOP
      INSERT INTO public.academy_lesson_blocks(
        version_id, block_key, position, block_type, title, content, required, points
      )
      VALUES (
        new_version_uuid,
        block_spec.value->>'key',
        (block_spec.ordinality - 1)::integer,
        block_spec.value->>'type',
        block_spec.value->>'title',
        block_spec.value->'content',
        coalesce((block_spec.value->>'required')::boolean, true),
        coalesce((block_spec.value->>'points')::integer, 1)
      )
      RETURNING id INTO block_uuid;

      IF block_spec.value ? 'evaluation'
         OR block_spec.value ? 'feedback'
         OR block_spec.value ? 'scoring' THEN
        INSERT INTO academy_private.lesson_block_keys(block_id, answer_key, feedback, scoring)
        VALUES (
          block_uuid,
          coalesce(block_spec.value->'evaluation', '{}'::jsonb),
          coalesce(block_spec.value->'feedback', '{}'::jsonb),
          coalesce(block_spec.value->'scoring', '{}'::jsonb)
        );
      END IF;
    END LOOP;

    validation_result := academy_private.lesson_validation(new_version_uuid);
    IF jsonb_array_length(validation_result->'errors') > 0
       OR jsonb_array_length(validation_result->'warnings') > 0 THEN
      RAISE EXCEPTION 'Lesson % failed validation: %',
        lesson_spec->>'lesson_id', validation_result;
    END IF;

    UPDATE public.academy_lesson_versions
      SET validation = validation_result
      WHERE id = new_version_uuid;

    UPDATE public.academy_lessons
      SET status = 'published',
          published_version_id = new_version_uuid,
          draft_version_id = new_version_uuid,
          updated_at = now()
      WHERE id = lesson_uuid;

    INSERT INTO public.academy_lesson_audit(
      academy_lesson_id, version_id, actor_id, action, details
    )
    VALUES (
      lesson_uuid, new_version_uuid, NULL, 'published',
      jsonb_build_object(
        'source', 'perfect_video_curriculum_v3',
        'version_number', new_version_number,
        'previous_version_id', previous_version_uuid,
        'preserved_existing_progress', true
      )
    );
  END LOOP;
END
$pv_release$;
